(window.STORIES=window.STORIES||[]).push(...[{"n": 148, "l": "الجزء 122 | علامات الساعة الكبري الجزء الثالث | المسيح الدجال الجزء الثاني", "u": "https://www.facebook.com/groups/710210019782034/permalink/824903601646008/", "t": "المسيح الدجال الجزء الثاني \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_واثنان_وعشرون\n#علامات_الساعة_الكبرى_الجزء_الثالث\n#المسيح_الدجال_الجزء_الثاني\nاتكلمنا المرة إللي فاتت عن صفات المسيح الدجال ، ووقفنا عند سؤال مهم، وهو: هل المسيح الدجال موجود دلوقتي ولّا لسه متولدش أصلا؟\nالمسيح الدجال موجود من أيام رسول الله ﷺ في جزيرة في البحر مُقيد بالسلاسل في دِير منتظر إن ربنا يأذن له بالخروج،\n◇والدير ده عبارة عن مكان للعبادة كان يتعبد فيه الرهبان، وكلمة الدير معناها في اللغة الآرامية المزرعة أو بيت الفلاح، فممكن يكون الدير هنا مقصود به بيت أو مزرعة أو مكان العبادة.\nفي واحد من الصحابة اسمه تميم الدّارِي قابل المسيح الدجال وجاء حكى لرسول الله ﷺ إللي حصل معاه، \nوكان لقاء تميم الداري بالمسيح الدجال سبب في إسلام تميم،\nواحنا منعرفش هل المسيح الدجال كان موجود من قبل بعثة رسول الله ﷺ ولّا لأ، فممكن إنه كان موجود قبل زمن رسول الله ﷺ وممكن لأ،\nومش معنى إن الأنبياء كانوا بيحذروا منه يبقى هو كان موجود على عهدهم،\nيعني مثلا في أنبياء بشروا برسول الله ﷺ ورسول الله ﷺ مكنش لسه موجود وكان بينهم وبينه زمن طويل،\n فالمؤكد عندنا بالدليل إنه كان موجود في زمن رسول الله ﷺ ولسه عايش لحد دلوقتي بحول الله وقدرته،\nلكن هل هو كان موجود قبل زمن رسول الله ﷺ أو لأ؟\n الله أعلم\nخلونا نشوف بقى قصة تميم الداري مع الدجال،\nعن فاطمة بنت قيس رضي الله عنها قالت :\nسَمِعْتُ نِدَاءَ الْمُنَادِي ، مُنَادِى رَسُولِ اللَّهِ ﷺ ، يُنَادِي:\n ( الصَّلاَةَ جَامِعَةً ).\n فَخَرَجْتُ إِلَى الْمَسْجِدِ فَصَلَّيْتُ مَعَ رَسُولِ اللَّهِ ﷺ ،\nفَكُنْتُ فِى صَفِّ النِّسَاءِ الَّتِى تَلِى ظُهُورَ الْقَوْمِ ، \nفَلَمَّا قَضَى رَسُولُ اللَّهِ ﷺ صَلاَتَهُ جَلَسَ عَلَى الْمِنْبَرِ وَهُوَ يَضْحَكُ ، فَقَالَ لِيَلْزَمْ كُلُّ إِنْسَانٍ مُصَلاَّهُ، ثُمَّ قَالَ أَتَدْرُونَ لِمَ جَمَعْتُكُمْ ؟\nقَالُوا : اللَّهُ وَرَسُولُهُ أَعْلَمُ .\n قَالَ :\n\"إِنِّى وَاللَّهِ مَا جَمَعْتُكُمْ لِرَغْبَةٍ وَلاَ لِرَهْبَةٍ ، وَلَكِنْ جَمَعْتُكُمْ لأَنَّ تَمِيماً الدَّارِىَّ كَانَ رَجُلاً نَصْرَانِيًّا فَجَاءَ فَبَايَعَ وَأَسْلَمَ....\"\nيعني واحدة من الصحابيات اسمها فاطمة بنت قيس بتحكي إن في يوم من الأيام سمعت منادي رسول الله ﷺ ينادي في الناس: الصَّلاَةَ جَامِعَةً \nفخرجت للمسجد و صلّت مع رسول الله ﷺ، ولما رسول الله ﷺ خلص صلاته جلس على المنبر وهو يضحك وقال للناس:\nكل واحد يخليه في مكانه، عارفين أنا جمعتكم ليه؟!\nفقال الصحابة : الله ورسوله أعلم\nقال لهم رسول الله ﷺ إنه مجمعهمش عشان في غنائم يوزعها أو في حرب هيخرجوا فيها،\nلكن جمعهم لأن واحد اسمه تميم الداري كان نصراني فجاء وأسلم وحكى له قصة حصلت معاه قبل ما ييجي ويُسلم،\n\" وَحَدَّثَنِى حَدِيثاً وَافَقَ الَّذِى كُنْتُ أُحَدِّثُكُمْ عَنْ مَسِيحِ الدَّجَّالِ....\"\nوالقصة إللي حكاها تميم الداري النصراني كانت عن لقائه بالمسيح الدجال وأحداث القصة وافقت كلام رسول الله ﷺ إللي كان بيقوله للناس عن الدجال، فرسول الله ﷺ جمعهم عشان يحكي لهم القصة، \n\"حَدَّثَنِى أَنَّهُ رَكِبَ فِى سَفِينَةٍ بَحْرِيَّةٍ مَعَ ثَلاَثِينَ رَجُلاً مِنْ لَخْم وَجُذَامَ ، فَلَعِبَ بِهِمُ الْمَوْجُ شَهْراً فِى الْبَحْرِ ، ثُمَّ أَرْفَئُوا إلَى جَزِيرَةٍ فِى الْبَحْرِ حَتَّى مَغْرِبِ الشَّمْسِ ، فَجَلَسُوا فِى أَقْرُبِ السَّفِينَةِ فَدَخَلُوا الْجَزِيرَةَ....\"\nيعني تميم الداري خرج في سفر في البحر مع ثلاثين من أصحابه من قبيلة لخْم وجُذَام،\nوهم راكبين في السفينة البحر هاج عليهم ولعب بهم الموج شهر كامل، وبعدين التجؤوا إلى جزيرة في البحر ونزلوا للجزيرة على قارب من قوارب السفينة الكبيرة ودخلوا الجزيرة،\nفلما دخلوا الجزيرة قابلتهم دابة غليظة الشعر وكثيرة الشعر، لدرجة إنهم مش عارفين وجهها من ظهرها من كثرة الشعر،\n\" فَلَقِيَتْهُمْ دَابَّةٌ أَهْلَبُ كَثِيرُ الشَّعَرِ ، لاَ يَدْرُونَ مَا قُبُلُهُ مِنْ دُبُرِهِ مِنْ كَثْرَةِ الشَّعَرِ...\"\nفلما شافوها اتخضوا وخافوا وقالوا لها : انتِ إيه\nفقالت لهم : أنا الجسّاسَة!\nفقالوا لها : وإيه الجساسة \nفمجاوبتش على سؤالهم وقالت لهم:\nشايفين الدِّير إللي هناك ده، روحوا هناك هتلاقوا فيه رجل مشتاق إنه يسمع عن أخباركم\nفلما سمع تميم وأصحابه الجساسة بتقول لهم عن رجل خافوا منها من إنها تكون شيطانة،\n\"فَقَالُوا : وَيْلَكِ مَا أَنْتِ ؟ فَقَالَتْ : أَنَا الْجَسَّاسَةُ ، قَالُوا :\n وَمَا الْجَسَّاسَةُ ؟ قَالَتْ : أَيُّهَا الْقَوْمُ ! انْطَلِقُوا إِلَى هَذَا الرَّجُلِ فِى الدَّيْرِ فَإِنَّهُ إِلَى خَبَرِكُمْ بِالأَشْوَاقِ،\nقَالَ لَمَّا سَمَّتْ لَنَا رَجُلاً فَرِقْنَا مِنْهَا أَنْ تَكُونَ شَيْطَانَةً\" \n☆ملحوظة : \nقيل إن الجسّاسة سُميت بالاسم ده لتجسُّسِها الأخبار للدجال، يعني كانت تعرف الأخبار وتيجي تحكيها للدجال.\nوالجساسة غير دابة الأرض إللي هتخرج في آخر الزمان وهي من علامات الساعة الكبرى \nفمشيوا بسرعة لحد ما وصلوا الدير، \nولما دخلوا لقوا رجل ضخم جدا، أعظم إنسان شافوه، ومتكتف ومتربط بالسلاسل بشدة،\n\"قَالَ فَانْطَلَقْنَا سِرَاعاً حَتَّى دَخَلْنَا الدَّيْرَ ، فَإِذَا فِيهِ أَعْظَمُ إِنْسَانٍ رَأَيْنَاهُ قَطُّ خَلْقاً ، وَأَشَدُّهُ وِثَاقاً ، مَجْمُوعَةٌ يَدَاهُ إِلَى عُنُقِهِ ، مَا بَيْنَ رُكْبَتَيْهِ إِلَى كَعْبَيْهِ بِالْحَدِيدِ...\"\nفسألوه: انت إيه\nفقال لهم :أنا متربط في السلاسل مش هعرف أروح في حتة، فلو قلت لكم أنا إيه هتسبوني وتمشوا وأنا عايز أعرف منكم معلومات، فانتم الأول جاوبوني إنتم مين وأنا هجاوبكم على سؤالكم\n\"قُلْنَا : وَيْلَكَ مَا أَنْتَ ؟ قَالَ : قَدْ قَدَرْتُمْ عَلَى خَبَرِي ، فَأَخْبِرُونِي مَا أَنْتُمْ ؟\nفقالوا له إنهم مجموعة من العرب ركبوا البحر والبحر هاج عليهم ولجأوا للجزيرة وقابلوا الجساسة وهي إللي أخبرتهم عن مكانه،\n قَالُوا : نَحْنُ أُنَاسٌ مِنَ الْعَرَبِ ، رَكِبْنَا فِى سَفِينَةٍ بَحْرِيَّةٍ ، فَصَادَفْنَا الْبَحْرَ حِينَ اغْتَلَمَ ( أي هاج ) ، \nفَلَعِبَ بِنَا الْمَوْجُ شَهْراً ، ثُمَّ أَرْفَأْنَا إِلَى جَزِيرَتِكَ هَذِهِ ، فَجَلَسْنَا فِى أَقْرُبِهَا ، فَدَخَلْنَا الْجَزِيرَةَ ، فَلَقِيَتْنَا دَابَّةٌ أَهْلَبُ كَثِيرُ الشَّعَرِ لاَ يُدْرَى مَا قُبُلُهُ مِنْ دُبُرِهِ مِنْ كَثْرَةِ الشَّعَرِ ، فَقُلْنَا : وَيْلَكِ مَا أَنْتِ ؟ فَقَالَتْ : أَنَا الْجَسَّاسَةُ\nقُلْنَا : وَمَا الْجَسَّاسَةُ ؟\nقَالَتِ : اعْمِدُوا إِلَى هَذَا الرَّجُلِ فِى الدَّيْرِ فَإِنَّهُ إِلَى خَبَرِكُمْ بِاْلأَشْوَاقِ . فَأَقْبَلْنَا إِلَيْكَ سِرَاعاً ، وَفَزِعْنَا مِنْهَا وَلَمْ نَأْمَنْ أَنْ تَكُونَ شَيْطَانَةً...\"\nفسألهم الرجل المربوط بالسلاسل عن نخل بَيْسَان،\nفسألوه: عايز تعرف إيه بالضبط عن نخل بيسان\nفسألهم عن نخلها لسه بيطلع ثمر ولّا لأ، فقالوا له إنه لسه بيطلع ثمر،\nفقال لهم إن النخل ده هييجي عليه يوم ومش هيثمر.\n☆بيسان مدينة في فلسطين.\n\"فَقَالَ : أَخْبِرُونِي عَنْ نَخْلِ بَيْسَانَ . قُلْنَا : عَنْ أَىِّ شَأْنِهَا تَسْتَخْبِرُ ؟ قَالَ : أَسْأَلُكُمْ عَنْ نَخْلِهَا هَلْ يُثْمِرُ ؟ قُلْنَا لَهُ : نَعَمْ . قَالَ : أَمَا إِنَّهُ يُوشِكُ أَنْ لاَ تُثْمِرَ...\"\nوسألهم عن بحيرة طَبَرية هل فيها ماء ولّا لأ،\nفقالوا له إن بحيرة طبرية مليانة بالماء فقال لهم إن الماء بتاع البحيرة ده هييجي في يوم ويخلص.\n☆بحيرة طبرية موجودة في شمال فلسطين على الحدود السورية الفلسطينية.\n\" قَالَ : أَخْبِرُونِى عَنْ بُحَيْرَةِ الطَّبَرِيَّةِ ؟ قُلْنَا : عَنْ أَىِّ شَأْنِهَا تَسْتَخْبِرُ ؟ قَالَ : هَلْ فِيهَا مَاءٌ ؟ قَالُوا : هِىَ كَثِيرَةُ الْمَاءِ . قَالَ : أَمَا إِنَّ مَاءَهَا يُوشِكُ أَنْ يَذْهَبَ...\"\n◇في هنا ملاحظة مهمة جدا\nبحيرة طبرية مش هتجف تماما غير لما يأجوج ومأجوج يخرجوا ويشربوها كلها، يعني بحيرة طبرية هتختفي بعد زمن المسيح الدجال مش قبله،\nلكن المقصود إن بحيرة طبرية تكون قبل ظهور المسيح الدجال غزيرة الماء جداً وده إللي تميم الداري يقصده لما قال إنها كثيرة الماء، لكنها هتقل شوية شوية وقبل ظهور الدجال هيقل فيها الماء، ولكنه لا ينعدم تماما،\nوإللي بيؤيد الكلام ده إن الماء على وجه العموم هيقل عند ظهور المسيح الدجال زي ما هنشوف،\nومش معنى إن منسوب بحيرة طبرية قل في زماننا دلوقتي يبقى المسيح الدجال هيخرج السنة الجاية مثلا\nطبعا لأ؛ لأن بكل بساطة باقي العلامات الصغرى إللي تسبق الدجال لسه مظهرتش،\nزي ظهور جبل الذهب وخروج المهدي وكمان فين المعاهدة بين الروم والمسلمين والملحمة الكبرى وفتح القسطنطينية\nكل الحاجات دي محتاجة لها وقت مش هتحصل في سنة ولّا اتنين مثلا، فمتقلقوش\nنرجع للدجال ونشوف بقية أسألته،\nسألهم عن عين زُغَرَ هل فيها ماء، فقالوا له إن العين دي مليانة مية وأهلها بيزرعوا منها.\n☆عين زُغر موجودة جنوب بحيرة طبرية بالقرب من مدينة أريحا المحتلة من اليهود في الجانب القبلي من الشام.\n\"قَالَ : أَخْبِرُونِى عَنْ عَيْنِ زُغَرَ ؟ قَالُوا : عَنْ أَىِّ شَأْنِهَا تَسْتَخْبِرُ ؟ قَالَ : هَلْ فِى الْعَيْنِ مَاءٌ ؟ وَهَلْ يَزْرَعُ أَهْلُهَا بِمَاءِ الْعَيْنِ ؟\n قُلْنَا لَهُ : نَعَمْ ، هِىَ كَثِيرَةُ الْمَاءِ ، وَأَهْلُهَا يَزْرَعُونَ مِنْ مَائِهَا....\"\nوبعدها سألهم عن نبي الأميين إيه إللي حصل معاه، فقالوا له إنه خرج من مكة وذهب ليثرب وقعد هناك، ونبي الأميين هو محمد ﷺ،\nفسألهم إذا كان العرب قاتلوه ولّا لسه، فقالوا له إن العرب قاتلوه وانتصر عليهم والعرب أطاعوه بعدها،\nفسألهم فعلا حصل كده؟ فأكدوا له فعلا الكلام، فقال لهم الأحسن لهم فعلا إنهم يطيعوه،\n قَالَ : أَخْبِرُونِى عَنْ نَبِىِّ الأُمِّيِّينَ مَا فَعَلَ ؟ قَالُوا : قَدْ خَرَجَ مِنْ مَكَّةَ وَنَزَلَ يَثْرِبَ،\n قَالَ : أَقَاتَلَهُ الْعَرَبُ ؟ قُلْنَا : نَعَمْ . قَالَ : كَيْفَ صَنَعَ بِهِمْ ؟ فَأَخْبَرْنَاهُ أَنَّهُ قَدْ ظَهَرَ عَلَى مَنْ يَلِيهِ مِنَ الْعَرَبِ وَأَطَاعُوهُ ، قَالَ لَهُمْ : قَدْ كَانَ ذَلِكَ ؟ قُلْنَا نَعَمْ.\nقَالَ : أَمَا إِنَّ ذَاكَ خَيْرٌ لَهُمْ أَنْ يُطِيعُوهُ...\"\n☆ملحوظة :\n تميم الداري أسلم سنة تسعة للهجرة بعد فتح مكة واستقرار أمر الإسلام وطاعة العرب لرسول الله ﷺ، \nواحنا لسه موصلناش في شرح السيرة للسنة التاسعة لكن بما إننا بنتكلم عن علامات الساعة فاحنا بنقول كل الأحاديث عن علامات الساعة من بداية بعثة رسول الله ﷺ لحد نهايتها\nبدأ بقى الرجل يكلمهم عن نفسه فقال لهم : \nأنا المسيح الدجال، وأنا قربت إني أخرج، ومفيش بلد إلا وهدخله في أربعين يوما إلا مكة وطيبة فهما محرمتان عليّ،\nكل ما حاولت إني أدخل واحدة منهم استقبلني ملك بيده السيف بيصدني ويبعدني عنها،\nوعلى كل طريق منها في ملائكة بيحرسوها، \n\"وَإِنِّى مُخْبِرُكُمْ عَنِّي ، إِنِّى أَنَا الْمَسِيحُ ، وَإِنِّى أُوشِكُ أَنْ يُؤْذَنَ لِى فِى الْخُرُوجِ ، فَأَخْرُجَ فَأَسِيرَ فِى الأَرْضِ فَلاَ أَدَعَ قَرْيَةً إِلاَّ هَبَطْتُهَا فِى أَرْبَعِينَ لَيْلَةً غَيْرَ مَكَّةَ وَطَيْبَةَ فَهُمَا مُحَرَّمَتَانِ عَلَيَّ كِلْتَاهُمَا ،\n كُلَّمَا أَرَدْتُ أَنْ أَدْخُلَ وَاحِدَةً أَوْ وَاحِداً مِنْهُمَا اسْتَقْبَلَنِى مَلَكٌ بِيَدِهِ السَّيْفُ صَلْتاً يَصُدُّنِى عَنْهَا ، وَإِنَّ عَلَى كُلِّ نَقْبٍ مِنْهَا مَلاَئِكَةً يَحْرُسُونَهَا....\"\nفقال رسول الله ﷺ تعقيبا على قصة تميم إن طيبة هي المدينة ، وسأل الناس: مش أنا كنت قلت لكم الكلام ده قبل كده؟!! فالناس قالوا له نعم،\nقَالَ رَسُولُ اللَّهِ ﷺ - وَطَعَنَ بِمِخْصَرَتِهِ فِى الْمِنْبَرِ يعني  بيضرب بعصاه إللي بيتكئ عليها المنبر:\nهَذِهِ طَيْبَةُ هَذِهِ طَيْبَةُ هَذِهِ طَيْبَةُ . يَعْنِى الْمَدِينَةَ أَلاَ هَلْ كُنْتُ حَدَّثْتُكُمْ ذَلِكَ ؟ . فَقَالَ النَّاسُ :نَعَمْ\"\nفقال لهم رسول الله ﷺ إنه عجبه إن كلام تميم وافق كلامه ﷺ عن مكة والمدينة وعن الدجال،\n\"فَإِنَّهُ أَعْجَبنِى حَدِيثُ تَمِيمٍ أَنَّهُ وَافَقَ الَّذِى كُنْتُ أُحَدِّثُكُمْ عَنْهُ وَعَنِ الْمَدِينَةِ وَمَكَّةَ...\"\n وده من تثبيت الله للناس، يعني واحد مكنش يعرف أي حاجة عن الدجال وجاء يقول نفس إللي كان رسول الله ﷺ بيقوله،\nفأكيد الكلام ده كان له تأثير إيجابي في قلوب الصحابة،\nزي كده إبراهيم عليه السلام لما طلب من ربنا إنه يُريَه كيف يُحيِي الموتى زيادة في تثبيت الإيمان في القلب\nرسول الله ﷺ لما سمع قصة تميم الداري ظن إن الدجال موجود في جزيرة في بحر الشام، لأن تميم ركب في بحر الشام،\nفقال للناس إن المسيح الدجال موجود في بحر الشام،\n\" أَلاَ إِنَّهُ فِى بَحْرِ الشَّامِ\"\n☆بحر الشام هو البحر الأبيض المتوسط في عصرنا دلوقتي.\nوبعدين رسول الله ﷺ قال لأ، ده في بحر اليمن على اعتبار إن بحر الشام بيتصل ببحر متصل ببحر اليمن،\n☆بحر اليمن إللي هو بحر العرب\nوالعرب زمان مكنوش بيسافروا غير في بحر الشام أو بحر اليمن، \n\" أَوْ بَحْرِ الْيَمَنِ\"\nوكل ده اجتهاد شخصي من رسول الله ﷺ على حسب المعطيات إللي قصاده عشان كده حصل تردد في اجتهاده فقال في الأول بحر الشام وبعدين قال بحر اليمن،\nواحنا عارفين إن الأنبياء ممكن يقعوا في السهو والشك والخطأ لكن الوحي لا يُقرّهم على كده ويأتي بتصحيح  الخطأ،\nفهنا الوحي جاء وصحح لرسول الله ﷺ المعلومة وقال إن المسيح الدجال لا موجود في بحر الشام ولا في بحر اليمن لكنه موجود في ناحية المشرق ناحية خُرَاسان،\nفقال رسول الله ﷺ إنه هيخرج من المشرق وأشار بإيده ناحية المشرق،\n\" لَا بَلْ مِنْ قِبَلِ الْمَشْرِقِ وَأَوْمَأَ بِيَدِهِ إِلَى الْمَشْرِقِ\"\nوخراسان ده إقليم فيه كذا مدينة، \nوطبعا الكلام ده بيرد على الناس إللي بتقول إن المسيح الدجال موجود في مثلث برمودا إللي محدش يقدر يدخله؛   لأن مثلث برمودا من جهة الغرب من المحيط الأطلسي\nوالمسيح الدجال موجود ناحية المشرق في إقليم خراسان زي ما رسول الله ﷺ قال\n☆ممكن حد يسأل سؤال ويقول إن الأقمار الصناعية ما تركت مكان في الأرض إلا ومسحته بالأجهزة المعقدة والدقيقة جداً، \nفليه العلماء ماكتشفوش مكانه\nنرد على السؤال ده بعكس السؤال،\nهل فعلاً الحضارة الغربية بأجهزتها الحديثة المتطورة دلوقتي كشفت على كل شيء ؟\nكشفت على كل شبر في الأرض؟ \nهو مش لسه في أماكن على الأرض لم تدخلها قدم إنسان؟\nهو مش في مغارات وكهوف محدش يعرف فيها إيه؟\nمش في أشياء في قاع المحيطات محدش يعرف إيه هي لحد دلوقتي؟\nطيب خلونا نفترض جدلا إن الأجهزة جابت كل مكان على الكرة الأرضية، هو مش ممكن ربنا يُعمي أبصار الناس عن مكان الدجال لأنه لا يريد لهم إنهم يعرفوا مكانه،\nكم مرة حاجة تضيع مننا وتبقى قصاد أعيننا ومنشوفهاش،\nفما بالكم بألله لما يريد إننا منعرفش حاجة عن مكان المسيح الدجال لأن وقته لسه مجاش\n◇يبقى باختصار كده نفهم من قصة تميم الداري إن المسيح الدجال موجود من زمن رسول الله ﷺ ومقيد بالسلاسل في دِير بجزيرة من جُزر البحر ومكان الجزيرة في جهة المشرق بالقرب من إقليم خراسان،\nوالدجال هيخرج من هناك، والدجال مش موجود في مثلث برمودا، \nواحنا منعرفش مين إللي قيده بالسلاسل كده، في علماء قالوا إن الملائكة هي إللي قيدته بس مفيش دليل من كلام رسول الله ﷺ على القول ده،\nلكن المؤكد إن الدجال مقيد بالسلاسل وده إللي يهمنا\nوكمان تقييد المسيح الدجال بالسلاسل في الجزيرة من الدلائل إنه مكنش هو ابن صياد، \n☆وده مين ابن صياد ده كمان\nشوفوا،\nلا تُذكر قصة الدجال إلا ويَذكر العلماء معاها قصة ابن صياد لأنها فعلا قصة عجيبة وكلها ألغاز\nعشان كده حصل اختلاف بين العلماء في ابن صياد هل هو المسيح الدجال ولّا لأ،\nولأن قصة ابن صياد فيها كلام كتير، فهنخليها للمرة الجاية إن شاء الله"}, {"n": 149, "l": "الجزء 123 | علامات الساعة الكبري الجزء الرابع | المسيح الدجال الجزء الثالث | الصياد", "u": "https://www.facebook.com/groups/710210019782034/permalink/825462734923428/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثلاث_وعشرون\n#علامات_الساعة_الكبرى_الجزء_الرابع\n#المسيح_الدجال_الجزء_الثالث\n#ابن_صيّاد\nوقفنا المرة إللي فاتت عند ابن صياد واختلاف العلماء فيه هل هو الدجال ولّا لأ،\nخلونا نشوف قصة ابن صياد وانتم احكموا بنفسكم إذا كان العلماء لهم حق في الاختلاف ده ولّا لأ\nابن صياد اسمه : صافي بن صياد أو صائد، \nوقيل عبد الله بن صياد أو صائد، وكان ابن صياد من يهود المدينة،\nوكان دجّالاً وبيتكهن للناس، فكانت تكهناته دي أحيانا بتكون صادقة وأحيانا كاذبة، فانتشر خبره بين الناس، وطلعت إشاعة إن هو الدجال،\nفرسول الله ﷺ  كان عايز يطّلع على أمره ويتبين حاله ويعلم حقيقته، ويُظهِر إبطال حاله للصحابة ، وإنه كاهن ساحر يأتيه الشيطان فيُلقي على لسانه ما يلقيه الشياطين إلى الكهنة،\nوخصوصا إن مكنش نزل لرسول الله ﷺ وحي في ابن صياد هل فعلا هو الدجال زي ما الناس بتقول ولّا لأ،\nفكان رسول الله ﷺ بيذهب لابن صياد ويسأله أسئلة يختبره بيها، وساعات كان يتخفى لابن صياد ويحاول يسمع من كلامه من غير ما ياخد باله،\nيعني مثلا في يوم من الأيام خرج رسول الله ﷺ مع عمر بن الخطاب ومعاه كم واحد من أصحابه متجهين ناحية ابن صياد،\nفكان ابن صياد قاعد بيلعب مع الصبيان وكان ساعتها قَارَب الحُلُم يعني قرب من البلوغ يعني عمره اثنا عشر سنة تقريبا،\nولما قرب رسول الله ﷺ من ابن صياد محسش بيه ابن صياد ولا أخد باله إن رسول الله ﷺ قرب منه لحد ما رسول الله ﷺ ضرب بيده، يعني خبط بإيده\nفابن صياد التفت وشاف رسول الله ﷺ، فقال له رسول الله ﷺ:\n\" أَتَشْهَدُ أَنِّي رَسُولُ اللَّهِ؟!!\"\nفنظر ابن صياد لرسول الله ﷺ وقال:\n\" أَشْهَدُ أَنَّكَ رَسُولُ الأُمِّيِّينَ\"\n☆ودي أول نقطة تلغبط، لأن الدجال إللي كان مقيد بالسلاسل سأل تميم الداري ما فعل نبي الأُمِّيِّينَ\nوراح ابن صياد سأل رسول الله ﷺ:\nأتشهد أني رسول الله؟ \nفتركه رسول الله ﷺ وقال :\n\" آمَنْتُ بِاللَّهِ وَبِرُسُلِهِ\"\nيعني ابن صياد بيدعي النبوة أمام رسول الله ﷺ، ورسول الله ﷺ تركه معملهوش حاجة عشان عايز يستغله ويسمع كلامه من غير ما ابن صياد يحس بكده،\nوبعدين سأله رسول الله ﷺ :\nانت بتشوف إيه؟! أو إيه إللي بيجيلك؟\nيعني مش انت رسول ايه بقى الوحي اللي بيجيلك،\nفقال ابن صياد: يأتيني صادق وكاذب!\nفقال له رسول الله ﷺ: انت اختلط عليك الأمر \nوبعدين قال له رسول الله ﷺ:\n\"إِنِّي قَدْ خَبَأْتُ لَكَ خَبِيئًا\"\nيعني أنا خبأت لك حاجة، تقدر تعرف إيه هي، وكان رسول الله ﷺ خبأ في نفسه 《الدخان》 من قوله تعالى:\n\" فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاء بِدُخَانٍ مُّبِينٍ\"\nفقال ابن صياد: \n\"هُوَ الدُّخُّ\" \nيعني يقصد الدخان، ولكنه قطمها على طريقة الكهان، فعرف رسول الله ﷺ مادته وأنها شيطانية، فقال له رسول الله ﷺ:\n\" اخْسَأْ فَلَنْ تَعْدُوَ قَدْرَكَ\"\nيعني لا تتعدى حدودك انت وأمثالك من الكهان إللي مش بيحفظوا من جمل الشياطين الكثيرة كلمة واحدة،\nيعني رسول الله ﷺ بيوضح الفرق بينه وبين ابن صياد وبيقول له انت مش رسول ولا حاجة،\nانت اخرك تعرف كلمة ولّا اتنين من كلام الشياطين، أما الأنبياء والرسل فإن الله تعالى يوحي إليهم من علم الغيب ما يوحي، فيكون الوحي واضح مفهوم كامل،\nفهنا عمر بن الخطاب قال لرسول الله ﷺ:\n\"دَعْنِي يَا رَسُولَ اللَّهِ أَضْرِبْ عُنُقَهُ\" \nيعني خليني أقتله ونخلص،  فقال له رسول الله ﷺ:\n\"إِنْ يَكُنْهُ فَلَنْ تُسَلَّطَ عَلَيْهِ وَإِنْ لَمْ يَكُنْهُ فَلا خَيْرَ لَكَ فِي قَتْلِهِ\"\nيعني لو هو الدجال مش هتقدر تقتله، ولو مش الدجال فمفيش فايدة من قتله،\nورسول الله ﷺ لم يقتل ابن صياد مع إنه ادعى النبوة لأن ساعتها ابن صياد كان لسه صغير مبلغش الحُلم حتى، يعني كان عمره حوالي اثنا عشر سنة زي ما قلنا من شوية،\nبعد كده رسول الله ﷺ ومعاه أُبَي بن كعب راحوا لمنطقة النخل إللي فيها ابن صياد زي بستان كده أو مزرعة، \nورسول الله ﷺ قعد يمشي براحة بين النخل والشجر عشان يراقب ابن صياد من غير ما ياخد باله لعله يعرف عنه حاجة،\nفشافه رسول الله ﷺ وهو نايم على رداء بتاعه وعمال يتمتم بكلمات كده بصوت واطي بكلام مش مفهوم،\nفرسول الله ﷺ عمال يقرب منه وبيحاول يسمع بيقول إيه،\nوإيه الكلام الغير مفهوم إللي بيقوله ده،\nفأم صياد خرجت من البيت إللي في المزرعة وشافت رسول الله ﷺ وهو بيتخفى لابنها وبيتسمع له فنادت على ابنها وقالت:\nيا صافِ محمد وراك\nفثار ابن صياد وغضب وقام من مكانه، فقال رسول الله ﷺ:\n\"لَوْ تَرَكَتْهُ بَيَّنَ\"\nيعني لو أمه مكنتش اتكلمت وكنت سمعت الكلام إللي عمال يقوله كنت عرفت إذا كان هو الدجال ولّا لأ،\nفرسول الله ﷺ فضل متحير في أمره ومعرفش إذا كان ابن صياد هو الدجال فعلا ولّا لأ،\nوانتشر الموضوع بين الناس إن رسول الله ﷺ بيشك في ابن صياد إن هو الدجال،\nوكان عمر يحلف بالله إن ابن صياد هو الدجال أمام رسول الله ﷺ ورسول الله ﷺ مش بيعترض عليه؛ لأن رسول الله ﷺ كان متوقف فيه وميعرفش إذا كان فعلا هو الدجال ولّا لأ،  \nفكان غالب عليهم الظن ان ابن صياد هو فعلا الدجال عشان كده عمر رضي الله عنه كان بيحلف ورسول الله ﷺ مكنش بيعترض،\nوقصة ابن صياد مع رسول الله ﷺ كانت في السنين الأولى بعد الهجرة يعني قبل قصة تميم الداري إللي قلنا عنها المرة إللي فاتت،\nفلما جاء تميم الداري وحكى قصته لرسول الله ﷺ نقدر نقول إن قصة ابن صياد بقت خلاص منسوخة،\nوإن ابن صياد مجرد واحد من الكُهان الدجالين وليس هو الدجال الأكبر إللي هيخرج آخر الزمان،\nلكن المشكلة بقى في إللي حصل بعد كده وخلّى العلماء يختلفوا،\nبعد موت رسول الله ﷺ حصلت حادثتين مع ابن صياد حيرت العلماء:\n◇الحادثة الأولى :\n ابن صياد أسلم وبقى غني عنده أموال كثيرة وكثرت ذريته،\nواحنا قلنا إن الدجال عقيم لا يُولد له،\n في مرة ابن صياد كان ماشي في طريق من طُرق المدينة الضيقة فقابله عبد الله بن عمر بن الخطاب وكان مع عبد الله مجموعة من أصحابه،\nفلقاه بقى أعور، وعينه عاملة زي العنبة الطافية\nفاستغرب عبد الله بن عمر وقال لابن صياد:\nإمتى حصل لعينك إللي أنا شايفه ده\nفقال له ابن صياد: معرفش\nفقال له ابن عمر: متعرفش؟!! وهي في رأسك؟!!\nيعني عينك في راسك ومش عارف امتى بقيت أعور\nفابن صياد قال لعبد الله بن عمر:\nلو أراد الله جعل عيني في عصاك \nفهنا عبد الله بن عمر غضب منه جدا وراح ماسك العصاية بتاعته ونزل ضرب على ابن صياد لحد ما كسر العصايا بتاعته على ابن صياد،\nفغضب ابن صياد غضب شديد وانتفخ، أه انتفخ\nوقعد ينتفخ لحد ما ملأ السكة الضيقة إللي كانوا واقفين فيها زي ما بنشوف في أفلام الكارتون كده\nوالناس إللي واقفة كلهم بقى مصدومين من منظر ابن صياد\nوالعجيب كمان إن عبد الله بن عمر بيقول والله ما حسيت إني ضربته ولا فاكر أصلا إني ضربته، وأصحابي إللي كانوا معايا هم إللي بيقولوا إني ضربته، \nوراح بعدها لأخته حفصة بن عمر زوجة رسول الله ﷺ وحكى لها إللي حصل،\nفقالت له حفصة: انت مالك ومال ابن صياد بتغضبه ليه، انت مش عارف إن الدجال هيخرج بسبب غضبة يغضبها\n◇الحادثة الثانية:\nابن صياد كان بيسمع كلام الناس فيه وإن هو الدجال فكان بيتأذى من كلامهم وكان دايما يدافع عن نفسه بأنه مش هو الدجال،\nخرج ابن صياد مرة للحج مع الناس، وكان من ضمن الناس واحد من الصحابة من الأنصار اسمه أبو سعيد الخدري،\nففي الطريق قعدوا يريحوا والناس اتفرقت كل واحد راح مكان واتبقى أبو سعيد مع ابن صياد،\nفهنا أبو سعيد الخدري رضي الله عنه خاف من ابن صياد من كتر الكلام إللي بيتقال عليه\nلأ وابن صياد جاب متاعه.. أغراضه وحاجته يعني ووضعها مع متاع أبو سعيد، يعني احنا قاعدين مع بعض مش هسيبك\nفأبو سعيد قال له :\nالجو حر فلو إنك وضعت أغراضك تحت الشجرة إللي هناك دي يكون أحسن،\nففعلا ابن صياد أخذ أغراضه ووضعها تحت الشجرة، وبعدها كان في غنم فراح ابن صياد حلب من الغنم وجاء لأبو سعيد باللبن يشربه، فقال لأبي سعيد: اشرب،\nلكن أبو سعيد مش عايز منه حاجة أصلا هو نِفسه يبعد عنه وده لازق فيه\nفقال له أبو سعيد: \nالحر شديد واللبن حار\nبيعتذر بلطف يعني عشان ميجرحوش ويقول له أنا مش عايز منك حاجة،\nفقال ابن صياد لأبي سعيد:\nأبا سعيد! لقد همَمْت أن آخذ حبلاً فأعلقه بشجرة ثم أختنق مما يقول لي الناس\nيعني من كتر الكلام أللي الناس بتقوله عنه فكر إنه ينتحر ويخلص من الهم ده كله،\nوبدأ بقى يدافع عن نفسه ويتلطف في الكلام مع أبو سعيد عشان يثبت له براءته، قال :\nيا أبا سعيد! مَن خَفِيَ عليه حديث رسول الله ﷺ ما خفي عليكم معشر الأنصار! \nيعني لو الناس معرفتش أحاديث رسول الله ﷺ؛ الأنصار أكيد عارفين كلامه ﷺ، ومش انت من أعلم الناس بحديث رسول الله ﷺ،\nطيب هو مش رسول الله ﷺ قال عن الدجال إنه كافر؟!\nطيب أنا مسلم\nمش رسول الله ﷺ قال عنه : هو عقيم لا يُولد له، طيب أنا تركت ابني في المدينة،\nمش رسول الله ﷺ قال: لا يدخل المدينة ولا مكة، طيب أنا جاي من المدينة ورايح مكة أهه\nفزي ما تقولوا كده ابن صياد صِعب على أبو سعيد الخدري ولقى إن كلام ابن صياد فعلا منطقي جدا، وقال أبو سعيد في نفسه:\nحتى كدت أن أعذره، يعني فعلا حسيته مظلوم، وإن مش هو الدجال،\nوراح ابن صياد مكمل كلامه:\nأما والله إني لأعرفه وأعرف مولده وأين هو الآن\nيعني أنا أعرف الدجال وأعرف أبوه وأمه وأعرف هو فين دلوقتي،\nفأبو سعيد اتصدم وقال له: تباً لك سائر اليوم، أيُسُّرك أنك ذاك الرجل؟\nيعني تحب إنك تكون انت الدجال، فابن صياد إللي عمال يدافع عن نفسه وكان عايز ينتحر بسبب كلام الناس قال:\nلو عُرِض عليَّ ما كرهت\nيعني لو اتعرض عليه إنه يكون الدجال مش هيعترض وهيوافق عادي جدا\nوحتى موته، محدش يعرف هو مات إزاي ولا هو فين أصلا، حصلت حادثة اسمها يوم الحَرّة حصل فيها قتال بين أهل المدينة وجيش يزيد بن معاوية،\nوفي اليوم ده فقدوا ابن صياد لا لقوه هو شخصيا ولا لقوا جثته وده من الأمور إللي زودت الشك عند الناس،\nوقالوا إن هو المسيح الدجال، لكن القول الراجح إن ابن صياد هو دجال من الدجالين وإنه ليس هو الدجال الأكبر،\nوشك رسول الله ﷺ فيه كان بسبب إن في صفات مشتركة بينه وبين الدجال، وربنا كان أوحى لرسول الله ﷺ صفات الدجال ولم يوحِ له مين هو الدجال\n☆ممكن حد يسأل ويقول : طيب هو مش الدجال مكتوب بين عينيه كافر وهيشوفها كل مؤمن ، إزاي رسول الله ﷺ مشافهاش\nبكل بساطة العلامة دي وغيرها من العلامات إللي جاءت في الدجال مش هتظهر غير في وقت فتنته لما يخرج على الناس آخر الزمان فيدعي الألوهية،\nفلو اعتبرنا ان ابن صياد كان فعلا الدجال فطبيعي إن رسول الله ﷺ ميشفش بين عينيه كلمة كافر،\nوزي ما قلنا إن الراجح إن ابن صياد مش هو الدجال\nكده احنا عرفنا مكان المسيح الدجال والعلاقة بينه وبين ابن صياد وعرفنا المكان إللي هيخرج منه،\nامتى بقى هيخرج، وإيه الظروف إللي هيخرج فيها\nاحنا قلنا إن الدجال هيخرج بعد الملحمة الكبرى وفتح القسطنطينية في آخر الزمان،\nأما الظروف إللي هيخرج فيها فالثلاث سنين إللي بيسبقوا خروج الدجال هيكونوا ثلاث سنوات شِدَاد،\n هيكون في فُرقة واختلاف وفتنة وفساد من أحوال الناس ، وخفة من الدين ،وسوء ذات بين، \nويصيب الناس فيها جوع شديد ، السنوات دي مفهمش مطر والماء على الأرض هيكون قليل جدا،\nفاكرين لما قلنا إن من علامات الساعة الصغرى توقف نزول المطر ، أهه في الثلاث سنوات قبل خروج الدجال هتحصل العلامة دي ،\nفي السنة الأولى تحبس السماء ثلث المطر، \nوالأرض هي كمان هتحبس ثلث النبات، وفي السنة الثانية السماء تحبس الثلث الثاني من المطر والأرض تحبس الثلث الثاني من النبات،\n وفي السنة الثالثة تحبس السماء الثلث الثالث من المطر والأرض تحبس الثلث الثالث من النبات،\n يعني مفيش ماء يبقى مفيش زرع، فمش هيلاقوا أكل يأكلوه ولا مية يشربوها، حتى الحيوانات هتهلك إلا ما شاء الله،\nقال رسول الله ﷺ:\n\" إن قبل خروج الدجال ثلاث سنوات شداد، يصيب الناس فيها جوع شديد، \nيأمر الله السماء في السنة الأولى أن تحبس ثلث مطرها، ويأمر الأرض أن تحبس ثلث نباتها، \nثم يأمر السماء في السنة الثانية فتحبس ثلثي مطرها، \nويأمر الأرض فتحبس ثلثي نباتها، ثم يأمر السماء في السنة الثالثة فتحبس مطرها كله، فلا تقطر قطرة،\n ويأمر الأرض فتحبس نباتها كله، فلا تنبت خضراء، فلا يبقى ذات ظَلْف إلا هلكت؛ إلا ما شاء الله\"\nوالمقصود من ذات الظلف هو الحيوانات، فالصحابة لما سمعوا كلام رسول الله ﷺ سألوه عن الناس هيعيشوا إزاي ومفيش لا زرع ولا ماء ولا حتى حيوانات يأكلوها،\nفقال لهم رسول الله ﷺ إنهم هيعيشوا على قول لا إله إلا الله والحمد لله والله أكبر، وهيقوم الذكر بمقام الطعام،\n \"قيل: فما يعيش الناس في ذلك الزمان؟ \nقال رسول الله ﷺ : التهليل والتكبير، والتحميد، ويجزئ ذلك عليهم مَجْزأة الطعام\"\n◇وهنا في فائدة وهي إن الأذكار بتعطي قوة للبدن، وده مش خاص بآخر الزمان فقط لكن خاص بكل زمان والدليل على كده إن فاطمة بنت رسول الله ﷺ لما اشتكت له وإنها عايزة خادم قال لها رسول الله ﷺ  إنه هيقولها على حاجة هي أحسن من الخادم، وهي إنها قبل ما تنام تسبح الله ثلاث وثلاثين مرة، \nوتحمد الله ثلاث وثلاثين وتكبر أربع وثلاثين، فالحديث موضح إن الذكر فيه فائدة في تقوية البدن، \nفحتى احنا لو احتاجنا للي يساعدنا في الأعمال فالحل إننا نكثر من ذكر الله، لأن فيه قوة للبدن،\nودي حقيقة فعلا مش مجرد كلام وعن تجربة شخصية عشان محدش بس يستبعد الموضوع وإنه صعب أو مستحيل\n☆طيب سؤال بقى،\nهو مش احنا قلنا إن المهدي هيكون قبل الدجال وإنه لما يحكم هيملأ الأرض عدل وربنا هيخرج له الثمار وينزل له الغيث من السماء،\nإزاي بقى يكون في قحط وقلة ماء وغذاء وفتن وفساد في أحوال الناس\nالمسيح الدجال هيخرج في زمن المهدي، والمهدي هيكون حاكم عادل وهيملأ الأرض عدل والعدل بييجي معاه كثرة الخير ونزول البركة من السماء،  \nلكن الوضع هيتغير قبل خروج الدجال بثلاث سنوات وربنا قادر، ومش معنى إن المهدي هيكون إمام عادل وخليفة راشد إن ميكونش في ناس فاسدين في الأرض وفي منافقين،\nفقبل خروج الدجال هيكون في فتن تصيب الناس عشان تطلع إللي جواهم ويميز الله الخبيث من الطيب ويتميز أهل الحق عن أهل الباطل،\nوساعتها ينقسم الناس لفريقين :\nفريق مؤمن لا نفاق فيه، وفريق منافق لا إيمان فيه،\nوالمؤمنين هم إللي هيقاتلوا الروم وينتصروا عليهم ويفتح الله عليهم القسطنطينية وروما وغيرها من البلاد،\nومتنسوش إن المهدي هيحكم سبع أو ثمان سنوات،\nفممكن لما يحكم هيقدر يملأ الأرض عدل وتفضل الفتن والاختبارات مستمرة عشان يحصل التمايز بين المؤمنين وغيرهم،\nلأن احنا عارفين إن المنافقين مش بيظهروا غير في عزة الإسلام وقوته، \nفإزاي ربنا يُظهر إللي في قلوبهم غير بالابتلاءات والفتن زي ما حصل في غزوة أحد وما بعد غزوة أحد وإللي حصل في غزوة الأحزاب لو تفتكروا\nفمن حكمة ربنا إن يكون في ابتلاءات وشدائد قبل الدجال عشان المؤمنين يتعلقوا بالله فتثبت قلوبهم في الامتحان الأكبر،\nوفي نقطة تانية وهي إن الدجال لما يخرج هيكون جايب معاه الخيرات كلها وهيأمر السماء إنها تمطر فتمطر ويأمر الأرض البُور إللي مفيهاش زرع إنها تطلع زرع فالزرع يخرج،\nفهنا الابتلاء يكون أشد على الناس ومش هيثبت أمامها غير المؤمن صادق الإيمان،\nومش كده وبس ده الدجال هيعمل حاجات تانية في الناس هنعرفها الجزء الجاي إن شاء الله بالتفصيل"}, {"n": 150, "l": "الجزء 124 | علامات الساعة الكبري الجزء الخامس | المسيح الدجال الجزء الرابع | فتنة المسيح الدجال", "u": "https://www.facebook.com/groups/710210019782034/permalink/825499204919781/", "t": "الدجال بعد الي هايعملو دا كلو كمان هايغضب ويدعي انه ال اله \n دا الي هايكون موجود الوقت دا هايتعمل منو بتاتس محمره\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وأربعة_وعشرون\n#علامات_الساعة_الكبرى_الجزء_الخامس\n#المسيح_الدجال_الجزء_الرابع\n#فتنة_المسيح_الدجال\nاتكلمنا المرة إللي فاتت والأجزاء إللي قبلها عن صفات المسيح الدجال وعن مكانه وعن الظروف إللي هيخرج فيها وعلاقته بابن صياد،\nعايزين بقى نعرف إيه هي فتنة المسيح الدجال إللي فتنته هي أعظم فتنة هتعدي على البشر زي ما رسول الله ﷺ قال:\n\" ما بين خلق آدم إلى قيام الساعة أمر أكبر من الدجال\"\nالدجال هيخرج من المشرق من إقليم خُراسان بسبب غضبة يغضبها، \nإيه سبب الغضب إللي هيغضبه ده الله أعلم\nمفيش أي حديث عن رسول الله ﷺ بيقول عن السبب إللي يخلي الدجال يغضب، \nإللي نعرفه إنه هيغضب فهيخرج، وطبعا كله بتقدير الله وبإذنه\nهيغضب الدجال ويخرج وأول ما يخرج يدعو إلى الإسلام ويقول: إنه مسلم، ويدافع عن الإسلام،\nوبعدين يدّعي النبوة ،وبعدين يدّعي الربوبية ويقول للناس إن هو الإله أو هو الله،\nوهيكون معاه نهرين بيمشوا معاه، نهر من نار ونهر من ماء أو في حديث تاني معاه جنة ونار ومعاه جبال الخُبز،\nويمشي في الأرض بسرعة كبيرة وفتنته عامة لكل أهل الأرض، \nمفيش بلد في الأرض إلا وهيدخلها الدّجال ما عدا  مكة والمدينة والمسجد الأقصى والطّور،\nقال رسول الله ﷺ:\nأنذرتكم المسيح ....إلى أن قال:\n\"يسير معه جبال الخبز وأنهار الماء.... يبلغ سلطانه كل مَنهَل\nلا يأتي أربعة مساجد الكعبة ومسجد الرسول والمسجد الأقصى والطور\"\nهيتبعه أول ما يطلع سبعين ألف من يهود أَصْبهان عليهم الطَّيَالِسَة،\nقال رسول الله ﷺ:\n\"يَتْبَعُ الدَّجَّالَ مِن يَهُودِ أصْبَهانَ، سَبْعُونَ ألْفًا عليهمُ الطَّيالِسَةُ\"\nوفي رواية تانية عليهم التِّيجان،\n☆والطّيْلسان معناه الثَّوبُ الَّذي به خُطوطٌ، وهو كساءٌ بيُوضَعُ على الكتِف، أَو يُحِيط بالبَدنِ، ويُعرَف بالشَّال،\nعارفين، زي الشِّماغ العربي كده\nعامة صورة الطيلسان هتلاقوها في التعليقات\n◇سؤال : هو في يهود في أصبهان\nأصبهان إللي هي أصفهان في زماننا دلوقتي وهي موجودة في إيران، وموجود فيها حوالي ثلاثين ألف يهودي على حسب الإحصائيات المقدرة لهم.\n◇طيب إزاي أصلا اليهود راحوا أصفهان أو إيران أو خلونا نقول بلاد فارس\nفاكريييين لما اتكلمنا في قصص الأنبياء عن الملك بُخْتُنصر  إللي حكم الأرض مع ثلاثة ملوك تانيين،\n وقلنا إن بختنصر دخل مدينة القدس وحرقها وقتل المقاتلين وسبى النساء والأطفال وحرق التوراة وخرب الحصون وهدم المساجد،\nوأخذ بختنصر معاه إلى أرض العراق إللي هي بلاد فارس أربعين ألف من اليهود كعبيد عشان يخدموا أهل بابل، \nأهه دي كانت بداية اليهود في بلاد فارس، وبعدين لما رجع اليهود للقدس زي ما حكينا في قصص الأنبياء مكنوش كلهم رجعوا، \nرفض بعض اليهود مغادرة بلاد فارس لأنهم لقوا فيها رغد العيش والأمان، وفضلوا عايشين فيها حتّى يومنا هذا\nوهيفضلوا عايشين هناك لحد زمن الدجال ولما يخرج هيتبعه منهم سبعون ألف،\nوهنا نلاحظ تواطئ اليهود مع الدجال، و إن دور اليهود لا ينتهي إلى قيام الساعة، وهم عايزين يحكموا العالم ويسيطروا عليه، \nوفي عقيدة اليهود إن الدجال اسمه المسيح بن داود، وأنه هيخرج في آخر الزمان ويرجّع لهم الملك،\nفلازم نعرف ونفهم كويس جدا إن اليهود أعداؤنا دائماً وأبداً ولازم نحذر منهم في كل عصر ووقت،\nواحنا شوفنا عملوا إيه مع أنبيائهم من أول موسى عليه السلام وعملوا إيه مع رسول الله ﷺ، فاحنا مش هنكون أغلى عندهم من الأنبياء يعني\n☆قبل ما نكمل الكلام عن باقي أتباع الدجال، خلونا نعرف معلومة بما إننا بنتكلم عن المشرق،\nرسول الله ﷺ كان دايما يقول إن الفتن تأتي من ناحية المشرق،\nوالمشرق إللي هي بلاد فارس: العراق وإيران، والمقصود بالفتن هنا هي الفتن العظيمة إللي هيكون لها تأثير في الأمة،\nولو لاحظتم هتلاقوا إن فتنة الخوارج خرجت من جهة المشرق من بلاد فارس العراق وإيران،\nوفتنة الشيعة الروافض من هناك والتتار دخلوا على المسلمين وذبحوهم من هناك،\nوالحروب إللي حصلت حتى في العصر الحاضر هتلاقوها في الجهة دي، \nوطبعا مش هتكلم عن داعش إللي بدأت من هناك،\nحتى لو كانت بدأت على منهج صحيح لكن حصل انحراف بعدين، واحنا شوفنا وسمعنا بلاويهم والله أعلم بحقيقتهم،\nفلو تتبعنا التاريخ الإسلامي هنلاقي إن منطقة خراسان مليانة بالفتن والحروب والمشاكل، \nلأن سكان الجهة دي بيتميزوا بحب العنف والدم والثورة وكانت بلاد فارس على طول في ثورات والوحيد تقريبا إللي استطاع يقمع الثورات في العراق كان الحجاج بن يوسف الثقفي، حكمهم عشرين سنة\nفالجهة دي عبارة عن بؤرة فتن فعلا زي ما رسول الله ﷺ قال: \" الفتن من جهة المشرق\"\nوالفتن هتختم بإن الدجال هيخرج من هناك، ويا لها من خاتمة بصراحة\nربنا ينجينا من الفتن ما ظهر منها وما بطن\nيبقى كده احنا عرفنا إن هيتبع الدجال سبعين ألف من يهود أصبهان وده كان الصنف الأول، \nالصنف الثاني إللي هيتبع الدجال هم الكفار بصفة عامة زي التُّرك أو التتار إللي وجوههم عاملة زي المَجَان المُطَرّقة،\nواحنا قلنا قبل كده إن المجان المطرقة معناها إن وجوههم مبطّطة وعريضة زي الترس إللي طُرق عليه بالحديد، وهيتبعه كمان العَجَم،\nأما الصنف الثالث إللي هيتبع الدجال فهم الكثير من المسلمين إللي هيفتنهم الدجال بالخوارق إللي هتظهر على يديه ،وخاصة الأعراب والنساء\n☆ممكن حد يسأل ويقول :\nيعني هي الناس هتبقى ساذجة للدرجة دي وتصدق إن واحد أعور هو الإله\nطيب يعني هم الناس إللي بيعبدوا البقر والفئران في عصرنا عصر التكنولوجيا والحضارة والعلم والفضائيات دول إيه مثلا\nالعالم بقى قرية صغيرة، يعني ممكن أي حد يعرف أي معلومة في أي مكان ومع ذلك في عبّاد للبقر وعباد للفئران وغيرها من الحيوانات والأصنام\nفيعني بالعقل كده حد يعتقد إن البقرة ولّا الفأر ده إله\nتخيلوا بقى إن الدجال هيخرج في وقت مجاعة وقحط وقلة ماء، فهييجي ويقول للناس أنا إله وماشي معاه نهر من نار ونهر من ماء وجبال الخبز،\nفالمظهر العام بيُبهر الناس خصوصا في المجاعة وإنهم عايزين ياكلوا،\nغير بقى التّجْريف والتشكيك في ثوابت الدين إللي شغال من دلوقتي من قبل حتى زمن الدجال،\nيعني مثلا مش بتسمعوا إللي يقول النصراني مش كافر ولا حاجة وهو بيعبد إلهه هو كمان، \nولو حد قال عليه كافر يعترض وإزاي تقولوا عليهم كده وهو انت ربنا عشان تقولوا عليهم كده\nولّا إللي تروح تقرأ قرآن على النصراني الميت في الكنيسة والناس تنبهر بيها وكلام بقى في مدحها مقلكوش\nالدين بيتغير ويتبدل واحنا مش حاسين ومش واخدين بالنا والجهل زاد جدا،\nحتى خطب الجمعة إللي المفروض الواحد بيروح ياخد منها شحنة إيمانية ولّا ياخد منها معلومة بقت مُوحّدة وبتتكلم عن أهمية النظافة والصبر على الغلاء وحب الزعماء والصبر على الغلاء من أجل الوطن\nفمتستغربوش لما تسمعوا إن الناس هتتبع الدجال وهو معاه الخوارق كلها،\nيعني لما الناس تؤمن به هيأمر السماء فتُنزل المطر ويأمر الأرض فتُنبت الزرع وتروح الماشية تأكل من الزرع فتكبر وتسمن وضرعها يتملى لبن في ساعتها،\nويروح لناس تانية ويدعوهم إنهم يؤمنوا به فيرفضوا ويكفروا به فيصبحون مُمْحِلِين، يعني عندهم قحط زيادة ومفيش زرع ولا ماء ويأخذ منهم حتى الأموال إللي كانت معاهم،\n\"ويَمُر بالخَرِبة فيقول لها أخرجي كنوزك\"\n يعني الدجال هيعدي على الأرض الخراب ويقول لها أخرجي كنوزك، فالأرض تسمع كلامه وتطلع الكنوز الموجودة في باطنها فتتبعه الكنوز دي وتمشي وراه وهو ماشي زي جماعات النحل لما بتمشي مع بعض كده،\nطبعا كل ده بإذن الله وهو ابتلاء واختبار للبشر عشان يظهر صادق الإيمان من الكاذب\nفواضح الفرق بين الفريقين، فاللي هيشوف الفرق أكيد هيبقى جواه سؤال:\nأنا هخسر إيه لو اتبعت الدجال، إللي بيتبعه بتتحل مشاكله الاقتصادية وبياخد الكنوز والأكل وإللي نفسه فيه، \nفي حين إللي بيخالفه هيعيش في مجاعة وضنك وقحط؟!\nوهو مش عارف إنه هيخسر دينه للأسف وإن كل إللي مع الدجال ده سراب ومش هيعرف إنه سراب غير لما يفوت الأوان،\nزي مافي ناس كتير جدا عرفت إن إللي وعد بيه دجال عصرنا طلع سراب وهم شاربين المُر دلوقتي ومحدش قادر يتكلم،\n☆محدش يفهمني صح\nالمهم يعني إن ناس كتير هتتبع الدجال ومن أكثر الناس دي  الأعراب والنساء وكل إللي معندوش علم بصفة عامة،\nالدجال هييجي للأعرابي مثلا ويسأله:\nأرأيتَ إن بعثتُ لك أباك وأمك أتشهد أني ربك؟\nيعني الدجال بيسأل الأعرابي لو أنا أحيَيْت لك أباك وأمك تشهد إني أنا ربك إللي بيحيي ويميت،\nفيقول الأعرابي: نعم\nفيستعين الدجال بالشيطاين ويجعلهم يتمثلوا بصورة أب وأم الأعرابي ده ويقولوا له:\nيا بُني اتبعه فإنه ربك\nفلما الأعرابي يشوف أبوه وأمه إللي خلاص ماتوا وعرفوا إيه إللي بعد الموت أكيد هم أدرى منه، فيسمع كلامهم ويتبع الدجال، \nمش عايزين بقى بعد ده كله الناس تتبعه\nإللي عبد البقرة وهي حيوان مش بيقدم حاجة ولا حتى بينطق سهل جدا يتبع المسيح الدجال بسبب الجهل إللي عايشين فيه،\nوقيسوا على كده كمان النساء\nالنساء هيُفتنوا بالدجال وهيكونوا من أكثر التابعين له، بسبب انتشار الجهل بينهن وغلبة العاطفة عليهن،\n\"حتى إن الرجل ليرجع إلى حَمِيمِه وإلى أمه وابنته وأخته وعمته فيوثقها رباطاً مخافة أن تخرج إليه\"\nيعني الرجل العاقل المسلم يذهب إلى نساء أهل بيته ويربطهم عشان خايف عليهم يخرجوا للدجال فيؤمنون به ويقعوا في فتنته،\nوانتم عارفين الناس بصفة عامة والنساء بصفة خاصة تحب تتفرج أد إيه على الحاجات الغريبة وتعرفها وتجربها، والناس بتقلد بعض حتى في الغلط\nواحنا مش هنروح بعيد، نظرة على الواقع هتخليكم تعرفوا ليه النساء هتتبع الدجال وتقع في فتنته،\nيعني مين أكثر حد بيتبع صيحات الموضة وبيقلد تقليد أعمى حتى لو كانت ضد العقل، مش النساء؟\nمين إللي كلمة تودينهم وكلمة تجيبهم وبكل سهولة ينخدعوا، مش النساء؟\nعشان كده أعداء الإسلام لما يكونوا عايزين يضربوا الإسلام في مَقتل يفتنوا النساء؛ لأن التأثير عليهن أسهل،\nولما تُفتن النساء مين إللي هيضيع في النص، الرجال طبعا، واحنا اتكلمنا قبل كده عن تأثير النساء على الرجال في جزء لماذا النساء فمش هعيد\n☆وطبعا مش عايز أفكركم برقص النساء قصاد اللجان الانتخابية وإنهم أكثر ناس نزلت انتخبت ومش هقولكم بقى نزلوا انتخبوا مين \nوانتم شوفتم بنفسكم المهازل إللي حصلت وبتحصل\nوكل ده بسبب الجهل المنتشر بينهن وتغلب العاطفة عليهن، \nوده على المستوى العام، \nشوفوا بقى على المستوى الخاص وفي الحوارات بين النساء هتلاقوا كمية جهل واتباع هوى مش ممكن\nوحتى لو حد حب ينصحهن يتهموه بالتشدد وغيرها وغيرها من الاتهامات المُعلبة الجاهزة\nده حتى مبيفكروش يتعلموا ولا يدورُّوا على الصح، هم شايفين إن كده صح وحابين ده فخلاص بقى هو ده الصح\nتخيلوا إن للأسف ده بقى حال غالبية النساء في زماننا دلوقتي، فلما الدجال ييجي بقى بالخوارق بتاعته ومعاه كنوز الذهب والفضة،\nوكمان مع قلة العلم في الأرض ومع غربة الدين ومعاه القحط والجوع، ساعتها وضع النساء هيبقى عامل إزاي\nأما النساء إللي هيكون عندها العلم وبتتقي الله ومربية نفسها على الدين فدي ربنا هيثبتها أمام الفتن بصفة عامة وأمام فتنة الدجال بصفة خاصة\nفاللي هيفرق بين الناس ساعتها بصفة عامة وبين النساء بصفة خاصة هو العلم وتقوى الله، في علم وتقوى ربنا هيثبّت الإنسان سواء كان رجل أو امرأة.\n☆ملحوظة عشان محدش يفهم غلط\nالنساء مش هتتبع الدجال عشان هم نساء، لأ النساء هيتبعوا الدجال عشان معندهمش علم والجهل منتشر بينهن،\nوكل ما كانت المرأة علمها قليل كل ما مشاعرها تغلبت عليها أكثر ووقعت في الخطأ،\nبدليل إن في نساء هتثبت أمام فتنة الدجال\nمن العلم إللي نتعلمه عشان نقدر نثبت أمام فتنة الدجال،\nهو إننا نعرف صفات الدجال عشان منتخدعش فيه،\nورسول الله ﷺ لما وصف الدجال للصحابة خاف إنهم يتلغبطوا في صفاته أو ييجي وقت الناس تنسى صفات الدجال إللي احنا قلناها قبل كده؛ فقال لهم كلمة جامعة تلخص الموضوع، قال:\n\"فَإِنْ أُلْبِسَ عَلَيْكُمْ فَاعْلَمُوا أَنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ\"\nيعني رسول الله ﷺ بعد ما وصف المسيح الدجال قال للصحابة وقال لنا احنا كمان لو حسيتم بلغبطة ومش عارفين تميّزوه اعرفوا إن ربكم ليس بأعور\n☆عشان كده لازم نربي نفسنا يا جماعة ونتعلم الدين صح ونتمسك بيه مش بس عشان فتنة الدجال، احنا ممكن منحضرهاش بس حياتنا مليانة بالفتن ولازم ناخد بالأسباب عشان منقعش فيها واحنا برده شايفين حوالينا ناس كتير بتقع مكناش نتوقع إنهم يقعوا،\nفالنجاة تكون بالعلم وتقوى الله\nربنا يثبتنا وإياكم على دينه  ولا يُزغ قلوبنا بعد الهداية ومعرفة الحق\nنرجع للدجال ونشوف هيقعد في الأرض أد إيه\n فتنة الدجال دي هتستمر في الأرض أربعين يوم،\nاليوم الأول في طوله كأنه سنة، يعني احنا السنة عندنا \nثلاثمائة وخمسة وستين يوماً، فبنقعد فترة معينة عشان نحس إن السنة خلصت،\nفاليوم الأول من الأربعين من أول طلوع الشمس إلى الغروب أو انتهاء اليوم كله بيعدي زي السنة في الطول، يعني باختصار اليوم بيمر ببطيء جداً، كمرور السنة على الحقيقة مش مجاز، يعني الشمس هتكون بتجري ببطئ شديد جدا،\nواليوم الثاني مقداره مقدار شهر،\nواليوم الثالث مقداره مقدار أسبوع، وباقي الأربعين يوم مقدارهم زي مقدار أيامنا العادية أربعة وعشرين ساعة،\nسُئِل رسول الله ﷺ عن مدة وجود الدجال في الأرض قال:\n\" أربعون يوماً، يوم كسنة، ويوم كشهر، ويوم كجمعة، وسائر أيامه كأيامكم\"\nوهنا الصحابة انتبهوا لنقطة مهمة وسألوا عنها رسول الله ﷺ، وهي الصلاة \n هل الصلاة هتكون خمسة برده في اليوم إللي زي السنة واليوم إللي زي الشهر واليوم إللي زي الأسبوع ولّا هيكون نظام الصلاة إزاي\nقالوا: يا رسول الله! فذلك اليوم الذي كسنة، أتكفينا فيه صلاة يوم؟\nفقال لهم رسول الله ﷺ:\n\" لا، ولكن اقْدُرُوا له قَدره\"\nيعني شوفوا في الأيام العادية أوقات الصلاة بينها أد إيه واحسبوا الساعات دي وصلوا،\nخلونا ناخد مثال للتوضيح\nبين الفجر والظهر في حوالي سبع ساعات ، فلو جاء الفجر وطلع اليوم الذي ظهر فيه المسيح الدجال، هيكون أول يوم من الأربعين إللي هو مقداره سنة،\nفالناس هتقد سبع ساعات وبعدها تصلي الظهر، ولأن الشمس لسه هتكون طالعة لأن اليوم طويل جدا هنحسب بين الظهر وبين العصر مثلا ثلاث ساعات، \n فنحسب ثلاث ساعات وبعدها نصلي العصر وهكذا لحد ما الصلوات الخمسة تخلص،\nولو الصلوات الخمس خلصت ولسه اليوم مخلصش يبقى الناس تصلي تاني الفجر في نفس اليوم على حسب عدد الساعات إللي بيحسبوها بين العشاء والفجر في الأيام العادية وهكذا.\n◇ومن هنا العلماء استفادوا حكم شرعي مهم جدا\nاحنا عارفين إن القطب الشمالي النهار فيه ستة أشهر والليل ستة أشهر،\nفإزاي مثلا المسلم هيصلي لو راح عاش هناك أو واحد من الناس إللي عايشين هناك أسلم هيصلي إزاي وعندهم ستة أشهر نهار وستة أشهر ليل\nفالعلماء أخذوا من حديث الدجال ده قاعدة تقدير الوقت للصلاة، يصلي الفجر أول ما تشرق الشمس، \nبعدها يصلي الظهر، بعدها يصلي العصر مع أن الشمس لسه موجودة، ثم يصلي المغرب والعشاء والشمس ما زالت موجودة،\nعشان نفهم بس إن الإسلام شريعة متكاملة وكل جزء منها بيكمل التاني مينفعش ناخد جزء ونسيب جزء،\nتخيلوا لو كان العلماء قالوا احنا ملناش دعوة بالدجال ده زمنه غير زماننا فملناش دعوة بالأحاديث دي،\nكانوا هيطلعوا قاعدة تقدير وقت الصلاة للناس إللي الشمس بتقعد عندهم فترة طويلة إزاي\nالمهم،\nالدجال هيتحرك في الأرض ويدخل كل بلد بسرعة زي ما قلنا، وهيعدي على الناس ويفتنهم فيتبعه من يتبعه ويَثْبُت من يُثبته الله،\nالسؤال بقى إزاي الواحد يحفظ نفسه من فتنة الدجال\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 151, "l": "الجزء 125 | علامات الساعة الكبري الجزء السادس | المسيح الدجال الجزء الخامس | النجاة من فتنة الدجال", "u": "https://www.facebook.com/groups/710210019782034/permalink/825534554916246/", "t": "الي هايحضر وقت نزول الدجال يهرب بسرعه وكمان الدجال هايكون شايل نهر من نار ونهر من جنه او جنه ونار روحو عند النار وطئطئو رؤسكم دي هتكون ماء بارده والدجال مش هايكون عارف \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وخمسة_وعشرون\n#علامات_الساعة_الكبرى_الجزء_السادس\n#المسيح_الدجال_الجزء_الرابع\n#النجاة_من_فتنة_الدجال\nوقفنا المرة إللي فاتت عند تساؤل مهم، وهو إزاي الإنسان يقدر يحفظ نفسه من فتنة الدجال،\nشوفوا، \nمن عدل ربنا ورحمته إنه مقدّرش علينا البلاء وسابنا من غير ما يقول لنا عن الطريقة إللي ننجي بيها نفسنا من البلاء أو الفتنة بصفة عامة أو من فتنة الدجال بصفة خاصة،\nأقول لكم زي إيه \nعارفين لما واحد يدخل مسابقة عشان يكسب جائزة كبيرة، أو يلعب لعبة مثلا مش بيكون فيها أدوات مساعدة؟\nوكل ما المستوى يكون أصعب كل ما عوامل المساعدة تزيد وتبقى أقوى\nولله المثل الأعلى في السماوات والأرض، أهه ربنا لما خلقنا في الدنيا وجعل لنا فيها الابتلاءات عشان يختبرنا أعطانا أدوات مساعدة نقدر نستعين بيها على تخطي الابتلاءات والفتن،\nفاللي هيستعمل أدوات المساعدة دي هو إللي هينجو، أما بقى إللي هيعمل فيها بطل ويعتمد على نفسه بس، أكيد هيخسر\nففتنة الدجال من اختبارات وابتلاءات الدنيا، بل هي أصعب وأخطر الابتلاءات في الدنيا، \nزي كده لما الواحد يوصل للسؤال الأخير في المسابقة أو يوصل للمستوى الأخير في اللعبة بيكون أصعب سؤال وأصعب مرحلة إللي وراها الفوز على طول\nوفتنة الدجال هي أخطر ابتلاءات الدنيا لأن الإيمان بالدجَّال يقود إلى الكفر الصريح، والكفر الصريح يقود إلى الخلود الأبدي في جهنم ربنا يعافينا\nعشان كده لازم نستعد كويس جدا قبل ما نواجه الفتنة العظيمة دي،\nطيب، إيه بقى العوامل المساعدة إللي ربنا أعطاها لنا عشان نحمي نفسنا من الدجال\n◇أولا: الاستعاذة من فتنة الدجال،\nيعني من قبل حتى ظهور الدجال احنا بندعوا ربنا وبنلجأ إليه إنه يحفظنا من فتنة الدجال، وبندعي ربنا في كل صلاة بعد التشهد الأخير وقبل التسليم من الصلاة زي ما رسول الله ﷺ علمنا قال:\n\" اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، 《وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ》، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ.\"\n◇ثانيا : الابتعاد عن الدجال\nيعني إللي يسمع إن الدجال خرج يبعد عنه فورا وميقربش منه؛ لأن احنا بطبيعتنا البشرية عندنا فضول وبنحب نتفرج، حتى لو على كوارث والله وخصوصا احنا كنساء\nفلما الناس تسمع بالدجال وإن معاه نهر من ماء ونهر من نار ومع كنوز الأرض ماشية وراه، فطبيعي إن الواحد هيبقى عايز يتفرج\nفلأن ربنا يعلم طبيعتنا دي قال لنا عن طريق رسول الله ﷺ إن إللي يسمع بالدجال يبعد عنه، لأن ممكن لو شافه يُفتن بيه وهو مفكر نفسه مؤمن ومفيش حاجة هتأثر فيه،\nقال رسول الله ﷺ:\n\"من سَمع بالدجال فليَنأَ عنه -فليبتعد عنه- فوالله إن الرجل ليأتيه وهو يحسب أنه مؤمن، فيتبعه مما يبعث فيه من الشبهات\"\n☆ومن هنا نقدر ناخد فائدة مهمة جدا\nوهي إننا منعرضش نفسنا للابتلاءات والفتن ونبعد عنها تماما، \nأقول لكم مثال من الواقع، \nلما واحدة تدخل مجموعة أو جروب عالفيس بوك مثلا وكل إللي فيها صور للنساء بيستعرضوا فيه لبسهم إللي على الموضة والشياكة والألوان و...و... وهي بتقول إنها بتتفرج بس، فضول يعني،\nإيه بقى إللي يضمن لها إنها متجيش يوم من الأيام وتعمل زيهم\nماهو ده باب فتنة أهه وشبهة للقلوب\nفاللي يسمع عن فتنة يبعد عنها مش يروح يتفرج، باب الفرجة ده ياما ضيّع ناس مكنوش يتخيلوا في يوم من الأيام إنهم هيضيعوا\nوزي برده الشاب إللي يروح مع أصحابه يتفرج عليهم وهم بيشربوا، بيشربوا بقى أي حاجة محرمة، المهم إن الفضول وإنه عايز يتفرج دفعه إنه يبقى زيهم، وخدوا أمثلة من دي كتير، \nفمحدش يستهين بموضوع الفضول والفرجة؛ لأن ده باب خطير جدا في فتنة الإنسان من غير ما ياخد باله\n☆سؤال بقى،\nإزاي هنبعد عنه وهو هيروح كل بلد في موجودة الأرض\nفي أماكن يقدر الناس يهربوا فيها بعيد عن الدجال،\nوالأماكن دي هي:\n¤أولا: الجبال،\n قال رسول الله ﷺ :\n\" لَيَفرَّنَّ الناس من الدّجال في الجبال\"\nيعني الناس هتهرب من الدجال ويتجهوا للجبال يعيشوا فيها طلباً للسلامة،\n¤ثانيا مكة والمدينة:\nالدجال هيدخل كل البلاد ما عدا مكة والمدينة زي ما رسول الله ﷺ قال:\n \"ليس من بلد إلا سيَطَؤُه الدجال، إلا مكة والمدينة\"\n¤ثالثا: المسجد الحرام والمسجد النبوي والمسجد الأقصى ومسجد الطور، ومسجد الطور ده زي ما قال العلماء هو على جبل الطور، المكان إللي كلم فيه موسى عليه السلام ربه الموجود في سيناء،\nفالأربع مساجد دول الدجال مش هيقدر يقرب منهم ولا يدخلهم،\nقال رسول الله ﷺ:\n\" لا يقرب أربعة مساجد مسجد الحرام ومسجد المدينة ومسجد الطور ومسجد الأقصى\"\n♤وهنا هيطلع لنا سؤال\nرسول الله ﷺ شاف في رؤيا له إن عيسى عليه السلام كان بيطوف حول الكعبة وشاف وراه المسيح الدجال بيطوف هو كمان، ورؤيا الأنبياء حق ووحي، إزاي ده بقى والمسيح الدجال لا يدخل مكة ولا يقرب المسجد الحرام\nالجواب على قولين:\n¤الأول : \nإن الدجال ممنوع من دخول مكة والمدينة لما يخرج في آخر الزمان وتظهر فتنته،\nأما قبلها أو في الزمن الماضي فمفيش أي نص شرعي بيدل على منع الدجال من دخول مكة والمدينة،\nفممكن رسول الله ﷺ لما شاف الدجال يطوف بالبيت الحرام كان قبل ظهور فتنته،\nوده كمان بيجاوب على الناس إللي سألت إزاي رسول الله ﷺ شك في ابن صياد إنه الدجال وابن صياد كان عايش في المدينة؛\nلأن الدجال ممنوع من دخول مكة والمدينة أو المساجد إللي قلنا عليها في وقت فتنته فقط\n¤القول الثاني:\nإن الرؤيا إللي رآها رسول الله ﷺ كانت رؤيا منام لها تعبير وتفسير، ومش معنى إن رؤيا رسول الله ﷺ وحي وحق إنها لازم تكون على ظاهرها، ممكن تيجي على سبيل ضرب الأمثال،\nيعني مثلا رسول الله ﷺ مرة شاف رؤيا إن الناس بتتعرض عليه وهم لابسين قُمُص يعني بلهجتنا جلاليب،\nفي إللي كان لابس جلابية قصيرة جدا لحد صدره وإللى كان لابس أطول شوية وإللي كان لابس جلابية متوسطة الطول، وشاف عمر بن الخطاب لابس جلابية بيجرها وراه،\nفلما حكى للصحابة سألوه إنت أوّلتها أو فسرت الرؤيا دي بإيه يا رسول الله،\nقال لهم : الدين!\nيعني ناس دينها أو تقواها أو إيمانها بسيط، وناس دينها متوسط لكن عمر دينه كبير جدا لدرجة إنه مغطيه وبيجره وراءه،\nمع إن رسول الله ﷺ نهى عن جر الثوب وإن ما أسفل الكعبين فهو في النار، لكن في الرؤيا الوضع مختلف والرؤيا لها تأويل\nفبعض العلماء عبّروا رؤيا رسول الله ﷺ للدجال وهو يطوف حول الكعبة بإن الطواف معناه الدوران، \nفطواف أو دوران عيسى عليه السلام حول الكعبة معناه إن له مهمة هيكملها وهي إنه هيطوف في الأرض لنشر الدين وإقامة أموره وإصلاح ما فسد منه،\nأما طواف الدجال فمعناه إن هو كمان له مهمة ناوي يكملها وهي الإفساد وفي الأرض وفتنة الناس.\nفاللي عايز يهرب من الدجال إما يهرب للجبال أو يسكن مكة والمدينة أو يلجأ للأربعة مساجد إللي قلنا عليهم.\n☆طيب ماهو في ناس أكيد مش هتقدر تروح الأماكن دي، تعمل إيه بقى ساعتها\nإجابة السؤال ده هتاخدنا للعامل الثالث أو الطريقة الثالثة للوقاية من فتنة الدجال:\n◇ثالثا: حفظ أول عشر آيات من سورة الكهف\nقال رسول الله ﷺ:\n\" مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الْكَهْفِ عُصِمَ مِنَ الدَّجَّالِ\"\nيعني إللي يحفظ أول عشر آيات من سورة الكهف وجاءه  الدجال فقرأ عليه العشر آيات دول؛ الدجال مش هيقدر يضره ولا يفتنه ولا يعمل له أي حاجة\nلكن مش هو إللي يروح يدوّر على الدجال\nلأ، هو يبعد عنه ويتجنب فتنته، ولو الدجال لحقه وقدر يوصل له يقرأ عليه العشر آيات الأولى من سورة الكهف،\nقال رسول الله ﷺ:\n\"فَمَنْ أَدْرَكَهُ مِنْكُمْ، فَلْيَقْرَأْ عَلَيْهِ فَوَاتِحَ سُورَةِ الْكَهْفِ\"\n☆طبعا أكيد هييجي في بالنا سؤال: اشمعنى يعني أوائل سورة الكهف ماحنا ممكن نقرأ أي آيات من أي سورة\nشوفوا، \nالعلماء قالوا إن سورة الكهف بصفة عامة ذُكر فيها كل الفتن إللي ممكن يتعرض لها أي إنسان في الدنيا،\nوهي فتنة المال في قصة صاحب الجنتين وفتنة المُلك أو السلطان في قصة ذو القرنين وفتنة العلم في قصة موسى والخَضر، وأهم الفتن فتنة الدين وده إللي بدأت به السورة وكان أبطالها أصحاب الكهف،\nوفتنة الدجال هي في الأصل فتنة في الدين داخل فيها فتنة المال والسلطان والعلم،\nوإللي تعرّض لفتنة الدين هم فتية أصحاب الكهف إللي هربوا من الملك الطاغية الجبار ودخلوا الكهف عشان يحفظوا دينهم،\nفلما الإنسان يحفظ الآيات دي ويعرف معناها هيقدر ينجو من الطاغية الدجال ويأمن على دينه زي ما نَجّى أصحاب الكهف من طاغيتهم وأمِنُوا على دينهم،\nفآيات سورة الكهف زي الدّرع كده إللي بيحمي الإنسان،\nطبعا والله أعلم، لأن دي أقوال العلماء واجتهاداتهم\n☆ملحوظة قصة أصحاب الكهف قلناها في قصص الأنبياء، وإللي مقرأهاش يراجع قصص الأنبياء \nيبقى كده الدجال هيمشي في الأرض ويفتن الناس، هيتّبعه من يتّبعه ويُثبّت الله من يُثبته لحد ما يوصل للمدينة، هيحاول يدخلها فتمنعه الملائكة من دخولها بالسيوف، في كل نَقَب أو في كل طريق ملائكة يحرسونها،\nفهيعسكر خارج المدينة في مكان اسمه الضَّرِيب الأحمر عند منقطة السّبْخة وهي الأرض الرملية المالحة التي لا تُنبت زرعاً،\nفساعتها المدينة هترجف ثلاث رجْفَات، يعني أرض المدينة هتهتز ثلاث مرات، بعد الاهتزاز ده هيخرج منها كل كافر ومنافق ويتوجه ليتبع الدجال،\nيعني الدجال مش هيقدر يفتن الناس في المدينة ويختبرهم، وفيهم ساعتها الكافر والمنافق والملحد وتارك الصلاة والمُسْتهزئ بالدين،\nفربنا هيجعل الأرض تهتز عشان الناس دي تخرج وتلحق بالدجال ويتبقى الصالحين في المدينة،\nقال رسول الله ﷺ:\n\"ليس من بلد إلا سيطؤه الدجال، إلا مكة والمدينة، وليس نقَب من أنقابِها إلا عليه الملائكة حافين تحرسها،\nفينزل بالسّبخة، فترجف المدينة بأهلها ثلاث رجْفات، يخرج إليه منها كل كافر ومنافق\"\nفي وسط الأحداث دي كلها واتّباع أكثر الناس للدجال هيخرج شاب مؤمن من خير الناس في الزمن ده ويواجه الدجال عشان يبين حقيقته للناس،\nالناس دلوقتي مخدوعين فيه وساعتها العلم قليل جدا والجهل منتشر بين الناس، وفي حديث بيقول إن الدجال هيخرج في وقت الناس نسيته أصلا ومبقاش في حد يُذَكّر الناس بفتنته ولا يُذكر اسمه على المنابر:\nقال رسول الله ﷺ:\n\" لا يخرج الدجال حتى يَذْهل الناسُ عن ذكره\"\n《الحديث الأخير ده\n فيه علماء قالوا عنه صحيح وعلماء قالوا ضعيف》\nلكن الأكيد إن الدجال هيخرج في وقت الجهل منتشر فيه والعلم قليل جدا\nفالشاب المؤمن ده هيخرج من المدينة ويقول للناس إن الرجل إللي بيدعي إنه إله هو المسيح الدجال إللي رسول الله ﷺ حذر منه، فجنود الدجال وأعوانه هيوقفوه ويمنعوه من إنه يروح للدجال ويسألوه:\n انت مش مؤمن بربنا؟!\nقال رسول الله ﷺ:\n\"يخْرُجُ الدَّجَّالُ فَيتَوَجَّه قِبَلَه رَجُلٌ منَ المُؤمِنين فَيَتَلَقَّاهُ المَسالح: مسالحُ الدَّجَّالِ، فَيقُولُونَ لَهُ: إلى أيْنَ تَعمِدُ؟ \nفيَقُول: أعْمِدُ إلى هذا الَّذي خَرَجَ، فيقولُون له: أو ما تُؤْمِن بِرَبِّنَا؟ \nفهيرد عليهم الشاب ويقول:\nربنا لا يخفى علينا احنا عارفينه كويس\n\"فَيقُولُ: \"مَا بِرَبنَا خَفَاء\"\nفالجنود هيقولوا : اقْتُلُوه\nوبعدين هيترددوا في قتله ويقول بعضهم لبعض:\nأليس قد نهَاكم ربكم أن تقتلوا أحداً دونه\nيعني مش الدجال قال لكم محدش يقتل حد غير لما تقولوا له الأول وترجعوا له،\nفهياخدوا الشاب المؤمن ويروحوا للدجال، وأول ما الشاب المؤمن يشوفه هيقول للناس :\nيا أيها الناس! هذا المسيح الدجال الذي ذكر رسول الله ﷺ !!\nفالدجال هيأمر جنوده إنه يأخذوه ويضربوه،\n \"فيَأمر به الدجال فَيُشبَّحُ -أي: يُمد ليُضرب هذا الشاب- فيقولوا: خذوه وشُجّوه، فيُوسع ظهره وبطنه ضرباً\"\nفبعد التعذيب ده الدجال هييجي يسأله:\nانت مش هتؤمن بي\nفالشاب هيقول له:\nانت المسيح الكذاب\nفالدجال هيقول لأتباعه لو أنا قتلت لكم الشاب ده وأحييته مرة تانية هتشكوا فيّ\nفالناس هيقولوا : لأ\nفيأمر الدجال أتباعه إنه يشقوا الشاب نصين بالمنشار من رأسه لحد رجله\nويأمرهم إنه يباعدوا بين النصين ويمشي بين النصين المقطوعين وبعدين يقول للشاب المقطوع ده: قُم!\nفيقوم الشاب واقف ويتجه ناحية الدجال وهو يضحك وكأنه لم يُقتل \nوطبعا الناس شايفين القدرات الخارقة للدجال ومذهولين\n☆إحياء الشاب مرة ثانية بأمر الله عشان يختبر الناس، لكن \nالدجال لا يملك أي شيء نهائي\nفالدجال هنا هيسأل الشاب المؤمن مرة ثانية:\nهل تؤمن بي\nفالشاب يرد عليه بكل إيمان وثقة بالله: \nما ازْددت فيك إلا بصيرة\nيعني أنا اتأكدت أكثر إنك انت الدجال الكذاب،\nبعدها على طول الشاب هيقول للناس :\nالدجال لن يُسلّط على أحد بعدي\nيعني الدجال مش هيقدر يؤذي أحد بعدي، أنا آخر واحد الدجال هيُسلط عليه،\nفالدجال هيقوم واخده عشان يذبحه فرقبة الشاب هتتحول لنُحاس بقدرة الله عز وجل، والسيف ميقدرش حتى يخدش رقبة الشاب،\nفيقوم الدجال ماسك الشاب من إيده ورجله وراميه في النار إللي معاه، ولكن في الحقيقة النار دي جنة زي ما رسول الله ﷺ أخبر،\nرسول الله ﷺ قال إن الدجال معاه نهر من نار ونهر من ماء، أو معاه جنة ومعاه نار، لكن الحقيقة غير إللي ظاهرة للناس،\nنار الدجال جنة، وجنته نار،\nوالنهر إللي من نار ده في الحقيقة  هو ماء بارد،\nعشان كده رسول الله ﷺ قال إللي يقابل الدجال ميدخلش جنته، لكن يتجه ناحية النار بتاعته ويوطي راسه ويغمض عينه ويشرب من نهر النار فهو ماء بارد\nقال رسول الله ﷺ:\n\"معه نهرانِ يجريان أحدُهما رأْيَ العينِ ماءٌ أبيضُ،\n والآخرُ رأيَ العينِ نارٌ تَأَجَّجُ ، فإمَّا أدْرَكَهُنَّ واحدٌ منكم ، فلْيَأْتِ النهرَ الذي يراه نارًا ، ثُمَّ لْيَغْمِسْ، ثُمَّ لْيُطَأْطِئْ رأسَهُ فيَشْرَبُ ، فإِنَّه ماءٌ بارِدٌ\"\nفالشاب المؤمن ده الدجال رماه في النار بتاعته على إنها نار ولكن في الحقيقة هي جنة والدجال نفسه ميعرفش المعلومة دي، رسول الله ﷺ هو بس إللي يعرف \nقال رسول الله ﷺ: \n\"لَأَنَا أعلمُ بما مع الدجالِ منَ الدجالِ\" \n☆نستفيد من موقف الشاب المؤمن ده أد إيه العلم الشرعي مهم جدا\nهو إيه الفرق بين الشاب ده وبين الناس إللي اتبعوا الدجال، مش العلم؟!\nدلوقتي في زماننا كل شوية تطلع فتنة وراء التانية والناس تحتار يا ترى الحق مع مين، يا ترى الحق فين،\nلكن لو الناس عندها علم مش هتبقى في حيرة كده،\nولولا إن الشاب ده كان عنده علم بالدجال وصفته وفتنته كان زمانه اتبعه زي باقي الناس،\nونستفيد كمان من موقف الشاب القيام في وجه الظلمة والإنكار عليهم 《للمُستطيع القادر》،\nمش إن واحد جبان يبقى متشجع في البداية للإنكار وبعدين أول ما يقف قصاد الجبار أو الطاغية خاف واتزلزل واعترف بالباطل وبقى كمان من أعوانه\nفاللي يقدر يقوم في وجه الظالم زي الشاب المؤمن ده كان مفيش مشكلة غير كده يبقى يبعد عن الفتن\nوبسبب موقف الشاب ده رسول الله ﷺ قال عنه:\n \"هذا أعظم الناس شهادةً عند رب العالمين\" \nلأنه شهد إنه الدجال أمام الناس على الرغم من كل إللي  تعرض له من أذى وابتلاء فقُتل شهيدا\nالدجال هيحاول يدخل المدينة أكثر من مرة لكن الملائكة تدفعه، وهيتجه خلف جبل أُحد،\nوفي رواية إنه هيطلع على جبل أحد ويقول للناس إللي معاه شايفين القصر الأبيض، يقصد مسجد رسول الله ﷺ،\nهنا هتدفعه الملائكة وتخليه يتجه ناحية الشام،\nقال رسول الله ﷺ:\n\" يأتي المسيحُ من قِبَل المشرق، وهِمّتُه المدينة، حتى إذا جاء دُبُر أُحد تلقّته الملائكة، فضربت وجهه قِبَل الشام\"\nاشمعنى الشام وإيه إللي هيحصل للدجال هناك، ده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 152, "l": "الجزء 126 | علامات الساعة الكبري الجزء السابع | المسيح الدجال الجزء السادس | هلاك الدجال ونزول عيسي", "u": "https://www.facebook.com/groups/710210019782034/permalink/825590611577307/", "t": "اهو سيدنا عيسي بنفسه هايطلع يقول للناس انو مش اله عشان بس اخواتنا المسيحين مش عارفين حاجه وهايطلع يقاتل اليهود  وزعيمهم الدجال \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وستة_وعشرون\n#علامات_الساعة_الكبرى_الجزء_السابع\n#المسيح_الدجال_الجزء_السادس\n#هلاك_الدجال_ونزول_عيسى\nاتكلمنا المرة إللي فاتت عن توجه المسيح الدجال للمدينة ومنع الملائكة له من الدخول للمدينة وإنها صرفته وخلته يروح للشام مع اتباعه،\nوالملائكة خلته يتوجه للشام نحو بيت المقدس لأن فيها هلاكه زي ما رسول الله ﷺ قال:\n\"حتى إذا جاء دُبر أُحد تلقته الملائكة فضُرب وجهه قبل الشام هناك يَهلك...هناك يهلك\"\nفي الوقت إللي الدجال كان متوجه فيه للشام كان المهدي بيجهز جيش من المؤمنين لقتال الدجال،\nبعد ما الجيش تجهز وساوُوا الصفوف جاء وقت صلاة الصبح فتقدم المهدي ليصلي بالمسلمين،\nفي الوقت ده بقى ينزل عيسى عليه السلام\nاحنا اتكلمنا في الجزء الأخير من قصص الأنبياء عن قصة رفع عيسى عليه السلام للسماء والسبب كان إيه،\nوقلنا إنه هيفضل في السماء لحد ما ييجي وقت نزوله في آخر الزمان، ونزول عيسى عليه السلام علامة من علامات الساعة الكبرى،\nقال تعالى:\n\"وَإِنَّهُ لَعِلْمٌ لِّلسَّاعَةِ \"\nفدلوقتي جاء وقت نزوله، هينزل من السماء عند المنارة البيضاء شرقي دمشق وهي لحد دلوقتي مكانها معروف في دمشق،\nوهيكون فيها معسكر المسلمين إللي بيجهزوا لقتال الدجال وإمامهم المهدي،\nهينزل عيسى عليه السلام وهو واضع كفيه على أجنحة مَلكين ولابس ثوبين مصبوغين، إذا طأطأ رأسه يعني إذا وطّى رأسه يقطر ماءً يعني ينزل منه قطرة بعد قطرة، وإذا رفعه تحدّر منه جُمَان كاللؤلؤ، \nيعني المقصود إن العَرق إللي بينزل منه زي حبات اللؤلؤ في الصفاء والحسن، فلا يحل لكافر يجد ريح نَفَسِه إلا مات، ونَفَسَه ينتهي حيث ينتهي طرفه،\nيعني في دائرة نصف قطرها مد بصر عيسى عليه السلام، كل الكفار في الدائرة دي يموتوا،\nوبعدين يروح للمسلمين هيلاقي الإمام بتاعهم وهو المهدي تقدم للصلاة فيرى عيسى عليه السلام فيقوم راجع للوراء ويقدم عيسى للصلاة لأن عيسى عليه السلام أفضل من المهدي والفاضل هو إللي بيتقدم للإمامة فيقول لعيسى عليه السلام:\n\" تَعَالَ صَلِّ لَنَا\"\nفيضع عيسى عليه السلام يده على ظهر المهدي بين كتفيه ويقول له:\n\" لاَ. إِنَّ بَعْضَكُمْ عَلَى بَعْضٍ أُمَرَاءُ، تَكْرِمَةَ اللَّهِ هَذِهِ الأُمَّةَ\"\n☆وفي هنا ملحوظة:\nعيسى عليه السلام رفض إنه يكون هو الإمام عشان متحصلش شبهة بين الناس،\nلأن رسول الله ﷺ قال:\" لا نبي بعدي\"\nفلو صلى عيسى عليه السلام بالناس إمام هتحصل لخبطة، والناس هتسأل هو تقدم عشان يكون نائب ولّا جاي بشريعة جديدة\nفصلى مأموم عشان يقفل باب الشبهة ده خالص، لأن عيسى عليه السلام هيطبق شريعة الإسلام بين الناس\nبعد الصلاة، عيسى عليه السلام هياخد الجيش ويتوجهوا لبيت المقدس عشان يقابلوا الدجال هناك عشان يقاتلوه هو واليهود إللي معاه، \nفيوصل عيسى لبيت المقدس ويقول عيسى عليه السلام: افتحوا الباب!\nفيفتحوا الباب ومن وراء الباب الدجال ومعه سبعون ألف يهودي كلهم معاهم سيوف مُحلاّة يعني مُزَينة ولابسين الطيلسان،\nفيدعوا عيسى عليه السلام اليهود للإسلام ولا يقبل منهم إلا الإسلام أو القتل خلاص مبقاش في جزية،\nفيُسلم منهم من يُسلم ويبقى الباقي على اليهودية فيقاتلهم عيسى عليه السلام ومعه جيش المسلمين،\nوأول ما الدجال يشوف عيسى عليه السلام يبدأ الدجال في الذوبان،\nيذوب الدجال زي ما الملح يذوب في الماء،\nويطلع يجري عايز يهرب من عيسى عليه السلام فيلحقه عيسى عند باب لُدْ ومعاه الحربة بتاعته فيقتل بها الدجال، ولو تركه عيسى لذاب ومات ولكن عيسى عليه السلام كان عايز يُورّي الناس دم الدجال على حربته ويثبت لهم إن ده الدجال مش إله،\nوبكده قتل مسيح الهداية مسيح الضلالة الدجال،\nوجيش المسلمين بيقاتل اليهود، فيهزم الله اليهود وتحصل فيهم مقتلة عظيمة ،ويروحوا يختبئوا من جيش المسلمين،\nفلا يبقى شيء مما خلق الله عز وجل يختبئ وراءه يهودي إلا أنطق الله ذلك الشيء ويقول:\n\" يا مسلم يا عبد الله ، هذا يهودي خلفي، فتعال فاقتله\"\nسواء كان الشيء ده حجر أوشجر أو دابة، أو حائط أو غيره،\nما عدا شجر الغَرقد لا ينطق لأنه من شجرهم ،واليهود بيزرعوه في فلسطين دلوقتي \nوبكده تنتهي فتنة الدجال، ويبدأ حكم عيسى عليه السلام قال رسول الله ﷺ:\n\"وَالَّذِي نَفْسِي بِيَدِهِ ، لَيُوشِكَنَّ أَنْ يَنْزِلَ فِيكُمْ ابْنُ مَرْيَمَ حَكَمًا عَدْلًا ، فَيَكْسِرَ الصَّلِيبَ ، وَيَقْتُلَ الخِنْزِيرَ ، وَيَضَعَ الجِزْيَةَ \"\nبعد مقتل الدجال، عيسى عليه السلام هيمسح على وجوه المؤمنين إللي معاه عشان يشيل من قلوبهم رعب المسيح،\nويخبرهم بدرجتهم في الجنة،\nوهم على الحال ده يُوحي الله لعيسى عليه السلام إنه أخرج عباد له مفيش لأي حد على وجه الأرض بهم طاقة،\nيعني محدش يقدر عليهم نهائي فيأمره الله إنه يأخذ المؤمنين إللي معاه ويتوجهوا لجبل الطور يحتموا فيه من البشر دول،\nقبل ما نعرف مين هم دول عندنا شوية أسئلة محتاجين إجابة\n☆السؤال الأول:\nإيه الحكمة من نزول عيسى عليه السلام \nنزول عيسى عليه السلام هيكون سبب من أسباب ظهور الإسلام إللي هو دين الأنبياء ظهورا كاملا على الأرض،\nلأن الناس اختلفت في عيسى عليه السلام أحزاب وطوائف وكل حزب متمسك برأيه،\nاليهود قالوا إنهم قتلوه، والنصارى قالوا إنه إله أو ابن إله،\nفلما ينزل عليه السلام هيوري الناس المختلفة فيه دول على حقيقة أمره ويفصل بينهم ويثبت لهم إنه مجرد بشر رسول ولم يُقتل زي ما اليهود قالوا، وإن هو إللي هيقتلهم وهيقتل زعيمهم الدجال،\nوكمان يُلزِم النصارى بالإسلام ولا يقبل منهم ولا من غيرهم الجزية؛ لأن في نزوله إقامة الحجة عليهم وإثبات بطلان كل الأديان ما عدا دين الإسلام \nوربنا قال:\n\"وَإِن مِّنْ أَهْلِ الْكِتَابِ إِلَّا لَيُؤْمِنَنَّ بِهِ قَبْلَ مَوْتِهِ \"\nيعني كل أهل الكتاب هيؤمنوا بعيسى عليه السلام في آخر الزمان قبله موته،\nوكمان عيسى عليه السلام بشر مخلوق من تراب، وكل البشر لازم يموتوا ويُدفنوا في الأرض:\n\"مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ\"\n☆السؤال الثاني:\nإزاي عيسى عليه السلام لا يقبل من الناس إلا الإسلام والمفروض إن باب التوبة اتقفل لأن خلاص الدجال خرج ورسول الله ﷺ قال:\n\"ثَلَاثٌ إِذَا خَرَجْنَ لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ ، أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا : \nطُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا ، وَالدَّجَّالُ ، وَدَابَّةُ الْأَرْضِ\"\nوالدجال قبل عيسى عليه السلام وعيسى هو إللي هيقتله، فإزاي بقى\nالعلماء لهم أقوال في المسألة دي، من الأقوال دي إن المذكور في الحديث هو الدخان مش الدجال، وحصل تصحيف، يعني حصل خطأ من الرواة في كتابة الكلمة، يعني بعض الرواة توهموا إن الكلمة اسمها الدجال بدل من الدخان،  لأن التشابه كبير بين الكلمتين، وخصوصا إن وَرَد في حديث تاني ذُكر فيه كلمة الدخان،\nويبقى الحديث :\n\"ثَلَاثٌ إِذَا خَرَجْنَ لَمْ يَنْفَعْ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ ، أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا : طُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا ، وَالدُّخَانُ ، وَدَابَّةُ الْأَرْضِ \"\nويبقى كده طلعنا من الإشكال خالص،\nلكن أقوى أقوال العلماء إن باب التوبة لا يُغلق إلا بتمام وقوع الثلاث آيات،\nيعني الدجال يخرج وبعدين دابة الأرض ويأتي وراها على طول طلوع الشمس من مغربها، \nفأول ما تخرج الشمس من مغربها كل الناس هيؤمنوا، وساعتها لا تنفع نفس إيمانها لم تكن آمنت من قبل،\nقال رسول الله ﷺ:\n\"لَا تَقُومُ السَّاعَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا ، فَإِذَا طَلَعَتْ وَرَآهَا النَّاسُ ، آمَنُوا أَجْمَعُونَ ،\n فَذَلِكَ حِينَ لَا يَنْفَعُ نَفْسَا إِيمَانِهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا\"\nوقال :\n\"مَنْ تَابَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا تَابَ اللَّهُ عَلَيْهِ \"\n☆السؤال الثالث:\nقلنا إن عيسى عليه السلام هيحكم بشريعة الإسلام، وشريعة الإسلام فيها الجزية، فإزاي بقى يغير في شريعة الإسلام ويضع الجزية، يعني لا يقبل الجزية من الكفار ولا يقبل إلا الإسلام\nمشروعية أخذ الجزية من أهل الكتاب إللي شرعها الإسلام هي شريعة مؤقتة غير دائمة تنتهي بنزول عيسى عليه السلام،\nلأن أهل الكتاب عندهم شبهة التمسك بشرعهم القديم: التوراة والإنجيل،\nفنزوله عليه السلام هيقطع عندهم شبهة التمسك بدين أنبياء أهل الكتاب، لأنهم شايفينه بعينه واقف قصادهم ،فعيسى عليه السلام لما يأتي ويكذبهم هتبطل دعواهم ، \nيعني أهه نبي من أنبياء أهل الكتاب بيقول لكم إن الإسلام هو الدين الحق وإللي بين إيديكم ده باطل\nفملهمش أي حجة دلوقتي في التمسك بالتوراة ولا بالإنجيل\nفعيسى عليه السلام مش هيغير من شريعة الإسلام حاجة،\n لأ ده حكم موجود أصلا في شريعة الإسلام، وهو إن الجزية لا تُقبل بعد نزول عيسى عليه السلام ،\nفإما الإسلام وإما القتل لأن ساعتها مفيش لأي حد حجة بعد ما شاف الآيات دي كلها وكمان عيسى عليه السلام بنفسه موجود\n☆السؤال الرابع:\n نَفَس عيسى عليه السلام بيقتل الكفار، طيب ليه مقتلش المسيح الدجال على طول ومقتلش اليهود وخلاص من غير ما يكون في قتال ومقتلش كل الكفار إللي في الأرض\nالمقصود هنا في وقت نزوله، يعني دي حاجة مؤقتة مش دائمة، فلما ينزل هيكون في كُفار في المنطقة إللي نازل فيها، زي ما كان في المدينة كده كفار ومنافقين خرجوا لما المدينة رجفت بهم ثلاث رجفات ،\nفلما ينزل عيسى عليه السلام وقت ما هو نازل؛ نَفَسه يقتل أي حد من الكفار موجود حوله؛ لأن مفيش دليل على إن الخاصية دي موجودة بعدين،\nوإلا فإزاي هيدعوا الناس للإسلام ويقاتل اليهود وغيرهم مع المسلمين عشان ينشر الإسلام في الأرض\n☆السؤال الخامس:\nليه عيسى عليه السلام يقتل الخنزير\nلأن الخنزير نجس ، وفي علماء قالوا بوجوب قتل الخنزير وفي علماء قالوا باستحباب قتل الخنزير، لأنه أسوأ من الفواسق الخمسة إللي رسول الله ﷺ أمر بقتلها،\nفعيسى عليه السلام لما ينزل هيحكم بشريعة الإسلام وهيقتل الخنزير يعني هيأمر بإعدامه ، \nوطبعا أكله وبيعه مُحرّم\nفاستدل العلماء على وجوب قتل الخنزير من فعل عيسى عليه السلام،\nوفيه دليل على إن الخنزير محرم في شريعة عيسى عليه السلام وفيه توبيخ عظيم للنصارى إللي بيدعوا إنهم على طريقة عيسى عليه السلام ثم يستحلون أكل الخنزير ويبالغون في محبته.\n☆يعني معنى كده إننا نقتل الخنزير في عصرنا\nأيوة يُقتل، وإللي يتمكن من قتله يقتله،\nلااااااكن\n◇أولا:\nلو الخنزير مِلك لأهل الذمة ولم يُظهروه وسط المسلمين، يعني مخليينه في بلد أو مكان بعيد عن المسلمين خلاص لا يُباح قتله، لكن لو أظهروه يُقتل.\n◇ثانيا:\nلو ترتب على قتل الخنزير مفسدة أكبر من قتله زي مثلا تحصل فتنة أو ضرر عظيم على المسلمين ، يبقى لا يُباح قتله، لأن درء المفاسد مُقدّم على جلب المصالح\nمين بقى العباد إللي خرجوا دول وليس لأحد بهم طاقة\nالعباد دول هم يأجوج ومأجوج\nإيه قصتهم وهيعملوا إيه ونهايتهم إيه،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 153, "l": "الجزء 127 | علامات الساعة الكبري الجزء الثامن | يأجوج ومأجوج", "u": "https://www.facebook.com/groups/710210019782034/permalink/827394991396869/", "t": "جماعه انا خفت\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وسبعة_وعشرون\n#علامات_الساعة_الكبرى_الجزء_الثامن\n#يأجوج_ومأجوج\nوقفنا المرة إللي فاتت عند العباد إللي ربنا أخرجهم ومفيش لأحد بهم طاقة يعني محدش يقدر عليهم، وقلنا إن العباد دول هم يأجوج  ومأجوج،\nلو تفتكروا في قصص الأنبياء اتكلمنا عن ذو القرنين ورحلته لمشرق الأرض ومغربها، لحد ما وصل مكان اسمه بين السدين  المكان إللي فيه يأجوج ومأجوج وبعد حوار مع الناس المتضررين من يأجوج ومأجوج قرر إنه يبني سد يحبس وراءه يأجوج ومأجوج عشان يمنع أذاهم عن الناس،\nوقصة ذو القرنين اتكلمنا عنها في قصص الأنبباء لو تفتكروا\nمين بقى يأجوج ومأجوج إللي ذو القرنين حبسهم وراء السد\n◇يأجوج ومأجوج اسمين لقبيلتين عايشين مع بعض،\n وهم من ذرية آدم عليه السلام من نسل نوح عليه السلام،\nفاكرين لما قلنا في قصص الأنبياء إن البشر كلهم من أبناء نوح عليه السلام الثلاثة :\nسام وحام ويافث \nسام وحام ذريتهم العرب واليهود..بني إسرائيل يعني،\nيافِث بقى هو إللي خرج من نسله يأجوج ومأجوج\nيعني هم من البشر العاديين،\nلا هم جِن ولا الواحد فيهم بينام على ودن ويستغطى بالودن الثانية ولا الخرافات إللي بتتقال عنهم دي\nلكنهم انعزلوا عن باقي البشر فأدى انعزالهم ده إنهم يتخلفوا عن باقي البشر،\nوالدليل على كده إنهم عاشوا بين السدين، ومفيش لغة عندهم خالص يتفاهموا بها مع باقي الناس،\nوكمان عاشوا على السرقة والقتل والنهب، يعني كل مظاهر الوحشية والإنعزال\nويأجوج ومأجوج غلب عليهم التناسل، يعني بيخلفوا كتير وعندهم أبناء كثير،\nوالدليل على كده إن يوم القيامة ربنا هيقول لآدم عليه السلام :\nيا آدم أَخرج بَعْث النار من ذريتك، يعني ربنا بيقول لآدم أخرج من ذريتك أهل النار ، \nقال رسول الله ﷺ:\n\"يَقُولُ اللَّهُ تَعَالَى : يَا آدَمُ ، فَيَقُولُ : لَبَّيْكَ وَسَعْدَيْكَ وَالْخَيْرُ فِي يَدَيْكَ ، فَيَقُولُ : أَخْرِجْ بَعْثَ النَّارِ...\"\nفآدم عليه السلام ميعرفش مين بعث النار فهيسأل ربنا:\nوما بعث النار؟!\nيعني إزاي أطلع بعث النار يارب، فربنا هيقول له من كل ألف تسعمائة وتسعة وتسعين في النار وواحد في الجنة،\n\"قَالَ وَمَا بَعْثُ النَّارِ ؟ قَالَ : مِنْ كُلِّ أَلْفٍ ، تِسْعَ مِائَةٍ وَتِسْعَةً وَتِسْعِينَ...\"\nفالصحابة خافوا وقالوا: \nيارسول الله ومين فينا الواحد ده\nفبشرهم رسول الله ﷺ إن الواحد ده منهم والألف من يأجوج ومأجوج،\n\"قالوا : يا رسول الله وَأَيُّنَا ذلك الواحد ؟ \nقال : \"أَبْشِرُوا فَإِنَّ مِنْكُمْ رَجُلًا ، وَمِنْ يَأْجُوجَ وَمَأْجُوجَ أَلْفًا\"\nفده يدل إن يأجوج ومأجوج من ذرية آدم عليه السلام وأعدادهم كبيرة جدا،\nفهم من ساعتها والسد مقفول عليهم، وكل يوم بيحفروا فيه عشان يحاولوا يطلعوا،\nفبيفضلوا يحفروا لحد ما يفتحوا فتحة في السد يدخل منها شعاع الشمس فيلاقوا نفسهم تعبوا فيقولوا خلينا نرجع ونكمل بكرة بعد ما يستريحوا،\nفلما يرجعوا تاني يوم يلاقوا الفتحة إللي حفروها في السد اتسدت بإذن الله والسد بقى أقوى،\nقال رسول الله ﷺ:\n\"يَحْفِرُونَهُ كُلَّ يَوْمٍ ، حَتَّى إِذَا كَادُوا يَخْرِقُونَهُ قَالَ الَّذِي عَلَيْهِمْ : ارْجِعُوا فَسَتَخْرِقُونَهُ غَدًا ، فَيُعِيدُهُ اللَّهُ كَأَشَدِّ مَا كَانَ\"\nفيبدأوا يحفروا تاني والفتحة تتسد وهكذا لحد ما ييجي اليوم إللي إللي ربنا مقدر فيه خروج يأجوج ومأجوج فيقول قائدهم : نكمل بكرة《إن شاء الله》،\nفيرجعوا يلاقوا الحفرة إللي حفروها زي ما كانت ويكملوا ويخرجوا بقى على الناس،\n\"حَتَّى إِذَا بَلَغَ مُدَّتَهُمْ - وَأَرَادَ اللَّهُ أَنْ يَبْعَثَهُمْ عَلَى النَّاسِ - قَالَ الَّذِي عَلَيْهِمْ : ارْجِعُوا فَسَتَخْرِقُونَهُ غَدًا إِنْ شَاءَ اللَّهُ - وَاسْتَثْنَى - قَالَ :\n فَيَرْجِعُونَ فَيَجِدُونَهُ كَهَيْئَتِهِ حِينَ تَرَكُوهُ فَيَخْرُجُونَ عَلَى النَّاسِ\"\nوهو نفس الوقت بعد قتل الدجال وانتصار المسلمين على اليهود، فربنا يُوحى لعيسى عليه السلام إنه يأخذ المؤمنين إللي معاه ويروحوا جبل الطور ويحتموا فيه من يأجوج ومأجوج،\nهيطلع عيسى عليه السلام والمؤمنين للجبل ويحتموا فيه، في الوقت ده بقى هيكون خروج يأجوج ومأجوج من كل طريق ومن كل مَمر،\nقال تعالى:\n\"حَتَّىٰ إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُم مِّن كُلِّ حَدَبٍ يَنسِلُونَ\"\nفلما يخرجوا هيمر أولهم على بحيرة طبرية فيشربون المية بتاعتها كلها، ويمر آخرهم يلاقي البحيرة فاضية ويقول إن كان في هنا ماء قبل كده،\nقال رسول الله ﷺ:\n\"وَيَبْعَثُ اللَّهُ يَأْجُوجَ وَمَأْجُوجَ وَهُمْ مِنْ كُلِّ حَدَبٍ يَنْسِلُونَ ، فَيَمُرُّ أَوَائِلُهُمْ عَلَى بُحَيْرَةِ طَبَرِيَّةَ فَيَشْرَبُونَ مَا فِيهَا ، وَيَمُرُّ آخِرُهُمْ فَيَقُولُونَ لَقَدْ كَانَ بِهَذِهِ مَرَّةً مَاءٌ\"\nوعلى فكرة بحيرة طبرية كبيرة جدا، يعني عشان تتصوروا أعداد يأجوج ومأجوج ،بحيرة طبرية دي حسب الإحصائيات ماؤها يكفي سكان بلاد الشام وهم حوالي ثلاثين مليون إنسان لمدة ثلاثين سنة\nيأجوج ومأجوج بقى هيخلصوها في كم ساعة، فأعدادهم كبيرة جدا وهم أقوياء جدا محدش يقدر عليهم وهيأكلوا الأخضر واليابس والناس هتهرب منهم\n☆في هنا بقى سؤال بقى،\nهل ربنا هيسلط يأجوج ومأجوج على كل الناس في الأرض ولا على العرب والمسلمين فقط\nالعلماء لهم قولين وكل قول له أدلته،\n¤القول الأول:\nإن فساد يأجوج ومأجوج عام لكل البشر.\n¤والقول الثاني:\nإن فساد يأجوج ومأجوج للعرب والمسلمين بصفة خاصة،\nوباقي الأرض ستتأثر بخروجهم بصفة عامة،\nيعني أكثر ناس هتتأثر بالابتلاء ده هم العرب والمسلمون،\nفاحنا منقدرش نُجزِم ونقول والله ده فتنة يأجوج ومأجوج للبشر كلهم، أو فتنهم للمسلمين فقط\nلكن أنا شخصيا بميل للرأي الثاني.. ليه\nرسول الله ﷺ دخل مرة وهو مفزوع على زوجته زينب بنت جحش رضي الله عنها وهو بيقول :\n\"لا إله إلا الله، ويل للعرب من شر قد اقترب،\nفُتح من ردم يأجوج ومأجوج مثل هذه وحلّق بين اصبعيه الإبهام والسبابة\n\"\nفرسول الله ﷺ خص العرب لأن الفتنة هتكون فيهم أكثر لأنهم أول من أسلم ومعظم المسلمين فيهم،\nوكمان أول ما يخرجوا هيشربوا بحيرة طبرية زي ما قلنا من شوية زي ما جاء في حديث رسول الله ﷺ، \nوبحرية طبرية مكانها بلاد الشام، فظاهر فتنتهم إنها هتكون في بلاد العرب،\nفده يدل إن يأجوج ومأجوج مع كثرتهم لم ينتشروا في الأرض كلها والتأثير الرئيسي كان في بلاد المسلمين،\nلكن زي ما قلت منقدرش نجزم بالموضوع ونقول إن قول معين هو الصحيح لأن كل فريق له أدلته\nبعد ما يأجوج ومأجوج يفسدوا في الأرض ويشوفوا إن بقى لهم الغَلبة في الأرض هيأخذوا السهام بتاعتهم ويرموها ناحية السماء، فترجع السهام بتاعتهم وهي مُخَضّبَة بالدم، يعني عليها دم فيقولوا:\n\"قهرنا مَن في الأرض وعَلَوْنا مَن في السماء\"\nقال رسول الله ﷺ:\n\"فَيَرْمُونَ بِسِهَامِهِمْ فِي السَّمَاءِ ، فَتَرْجِعُ مُخَضَّبَةً بِالدِّمَاءِ ، فَيَقُولُونَ : قَهَرْنَا مَنْ فِي الْأَرْضِ ، وَعَلَوْنَا مَنْ فِي السَّمَاءِ\"\nوكلامهم ده بيجاوب على سؤال مهم وهو:\n☆ليه يأجوج ومأجوج هيدخلوا النار زي ما قلنا في الحديث بتاع آدم عليه السلام من شوية إنهم أهل النار،\nفإزاي بقى يدخلوا النار وهم مبلغهمش رسالة الإسلام ومقفول عليهم السد\nمن خلال كلامهم واضح إنهم عارفين إن في حاجة اسمها إله وإنه في السماء وكفروا به أهه وقالوا إنهم قتلوه،\nوده يدل على إن في رسالة وصلتهم من الله سواء رسالة الإسلام  عن طريق رسول الله ﷺ بطريقة إحنا منعرفهاش، أو رسالة من الأنبياء السابقين\nواحنا عارفين إن ربنا لا يُعذب أحد إلا لما يُقيم عليه الحُجة سواء في الدنيا عن طريق رسول أو في الآخرة عن طريق الإختبار،\nفأي أحد يموت ولم يبلغه دعوة الإسلام ربنا هيعامله معاملة أهل الفترة وهيمتحنه يوم القيامة زي ما قلنا قبل كده،\nفالشاهد من الكلام إن يأجوج ومأجوج كفرة، كفروا بالله والكافر جزاؤه النار\nفي الوقت إللي يأجوج ومأجوج رموا السهام للسماء ورجعت لهم فيها دم وقالوا قهرنا مَن في الأرض وعَلَونا مَن في السماء كان عيسى عليه السلام مع المؤمنين في شدة و جوع لدرجة إن رأس الثور أفضل عند الواحد فيهم من إللي يلاقي مائة دينار في زماننا دلوقتي،\n\"وَيُحْصَرُ نَبِيُّ اللَّهِ عِيسَى وَأَصْحَابُهُ حَتَّى يَكُونَ رَأْسُ الثَّوْرِ لِأَحَدِهِمْ خَيْرًا مِنْ مِائَةِ دِينَارٍ لِأَحَدِكُمْ الْيَوْمَ\"\nيعني من شدة الجوع الواحد منهم لو لقى رأس ثور إللي هو تقريبا مفيهوش أي لحم أو أي حاجة ممكن يستفيد بها منه أفضل من إن الواحد مننا يبقى عنده نصف كيلو ذهب،\nفعيسى عليه السلام والمؤمنين معاه هيدعوا ربنا إنه يخلصهم من يأجوج ومأجوج،\nفيستجيب الله دعاءهم ويرسل النّغف على رقاب يأجوج ومأجوج فيقتلوهم كلهم ويموتوا كنفس واحدة،\nيعني كلهم هيقعوا ميتين في نفس اللحظة كأنهم نفس واحدة،\n\"فَيَبْعَثُ اللَّهُ عَلَيْهِمْ نَغَفًا فِي أَقْفَائِهِمْ ، فَيَهْلِكُونَ\"\nوالنّغف ده نوع من الديدان بيكون في أنف الغنم عادة،\nفتمتلأ الأرض بجثث يأجوج ومأجوج،\nفينزل عيسى عليه السلام وأصحابه من جبل الطور ويلاقوا الأرض امتلأت بجثثهم وغير صالحة للعيش عليها وريحة الأرض نتنة بسبب جثثهم،\n\"ثُمَّ يَهْبِطُ نَبِيُّ اللَّهِ عِيسَى وَأَصْحَابُهُ إِلَى الْأَرْضِ فَلَا يَجِدُونَ فِي الْأَرْضِ مَوْضِعَ شِبْرٍ إِلَّا مَلَأَهُ زَهَمُهُمْ وَنَتْنُهُمْ\"\nفيدعو عيسى عليه السلام  ربنا إنه يخلص الأرض منهم ومن نتن ريحتهم، فربنا هيرسل طيور ضخمة تشيل جثث يأجوج ومأجوج وترميهم في المكان إللي ربنا يريده،\n\"فَيَرْغَبُ نَبِيُّ اللَّهِ عِيسَى وَأَصْحَابُهُ إِلَى اللَّهِ فَيُرْسِلُ اللَّهُ طَيْرًا كَأَعْنَاقِ الْبُخْتِ فَتَحْمِلُهُمْ فَتَطْرَحُهُمْ حَيْثُ شَاءَ اللَّهُ\"\n وبعد كده يُنزل ربنا المطر فيغسل الأرض كلها ومن نضافتها هتبقى الأرض زي المرآة،\n\"ثُمَّ يُرْسِلُ اللَّهُ مَطَرًا لَا يَكُنُّ مِنْهُ بَيْتُ مَدَرٍ وَلَا وَبَرٍ ، فَيَغْسِلُ الْأَرْضَ حَتَّى يَتْرُكَهَا كَالزَّلَفَةِ\"\nوتبدأ بقى فترة حكم عيسى عليه السلام في الأرض،\nقبل ما نعرف إللي هيحصل بعد حكم عيسى عليه السلام، عندنا كم سؤال عايزين مجاوب عليهم،\n ◇ السؤال الأول:\nهل احنا ممكن نعرف مكان يأجوج ومأجوج ونشوفهم ونقدر نوصل لهم وسط التقدم العلمي إللي إحنا فيه ده\nإجابة السؤال ده زي ما جاوبنا على سؤال هل نقدر نعرف مكان الدجال ولّا لأ،\nممكن واحد يقعد كده على جوجل إيرث google earth ومش وراه غير إنه يبحث عن يأجوج ومأجوج في كل شبر من الكرة الأرضية، ويستعمل كل أساليب التقدم العلمي في البحث بتاعه ومع ذلك ميلاقهمش\nليه\nلأن ربنا لم يأذن في إن حد يعرف مكانهم، وهم لسه مش هيخرجوا دلوقتي، \nفاكرين لما اتكلمنا عن هجرة رسول الله ﷺ للمدينة وإنه اختبأ في غار حراء والمشركين وصلوا لحد باب الغار وكانوا واقفين على باب الغار ولو واحد فيهم بص تحت رجله بس كده كانوا هيشوفوه، ومع ذلك مفيش واحد منهم كلّف نفسه إنه ينظر داخل الغار لأن ربنا لم يأذن لهم وأعماهم عن رسول الله ﷺ\nفممكن ربنا يعمي بصر الناس عن مكان يأجوج ومأجوج، \nوغير كده مين قال إن مكانهم فوق الأرض،\nمش يمكن تحت الأرض\nمش احنا قلنا من شوية إنهم بيحفروا لحد ما يشوفوا شعاع الشمس، معنى كده إن شعاع الشمس مش واصل لهم أساسا\nده غير كل ده احنا مش مطلوب مننا إننا ندور عليهم أصلا،\nوده هياخدنا للسؤال التاني وهو:\n☆إيه الحكمة إن ربنا يقول لنا على يأجوج ومأجوج واحنا إحتمال كبير منحضرهمش أصلا، والناس إللي قبلنا كمان محضروهمش\nاحنا عارفين إن المؤمن هو إللي بيدخل الجنة،\n《أقصد يعني بدون سابقة عذاب أو عقاب، لأن المسلمين بصفة عامة هيدخلوا الجنة لكن ممكن يدخلوا بعد ما يتعذبوا على قدر ذنوبهم》\nلكن أنا بتكلم عن المؤمنين الخُلّص\nطيب من أركان الإيمان الستة :الإيمان بالغيب...ويأجوج ومأجوج من الغيبيات،\nفربنا بيقولنا عن حاجات لو قسناها بالعقل متركبش، فهنا يبان صدق الإيمان بالغيب، وده الفرق بين المؤمن والكافر إللي عايز كل حاجة يشوفها قصاده عشان يقتنع بها وإنها موجودة.\n☆السؤال الثالث:\nإزاي ذو القرنين وهو كان حاكم عادل يحبس ناس ويعرضهم للهلاك وخصوصا إنهم بيخلفوا كثير،\nوأصلا ناس بالكمية دي بياكلوا إيه وإزاي عايشين السنين دي كلها \nلما ذو القرنين حبس يأجوج ومأجوج كان بقدر الله،\nيعني ربنا لما بيقدّر على الإنسان حاجة بيخليه يتكيف مع إللي حصل له ده\nيعني مثلا في البلاد الحارة عند خط الإستواء هتلاقي البشر بشرتهم سمراء وشعرهم مجعد ولهم أكل معين، \nغير البشر إللي في أوروبا، بشرتهم بيضاء وشعرهم ناعم وأكلهم مختلف،\nفربنا لمّا قدّر على يأجوج ومأجوج إنهم يتحبسوا وراء السد أعطاهم القدرة إنهم يتكيفوا مع بيئتهم،\nده غير إننا منعرفش أصلا إيه هي طبيعة أكل يأجوج ومأجوج...هل بياكلوا اللحوم ولّا بياكلوا إيه بالضبط\nويمكن يكون عندهم موارد للغذاء من الناحية الثانية من السد،\nويمكن ربنا أمسك عنهم الجوع والعطش لحد ما يأذن لهم بالخروج... إحتمال وارد ولّا لأ \nفكل دي إحتمالات\nلأننا معندناش أي دليل يقول لنا طبيعة الأكل إللي يأجوج ومأجوج عايشين عليه السنين دي كووولها\nفهو منعهم وفي نفس الوقت قدّر لهم الرزق..إزاااي ..ده تقدير ربنا مش شغلنا \nهيبدأ بقى عيسى عليه السلام يعيش في الأرض مع المؤمنين، هيعيش أد إيه والحياة هتبقى عاملة إزاي بعد كده،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 154, "l": "الجزء 128 | علامات الساعة الكبري الجزء التاسع | طلوع الشمس من مغربها وخروج الدابه", "u": "https://www.facebook.com/groups/710210019782034/permalink/827405924729109/", "t": "إللي يعيش لحد ما ينزل عيسى عليه السلام  يوصل له سلام رسول الله ﷺ،\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثمانية_وعشرون\n#علامات_الساعة_الكبرى_الجزء_التاسع\n#طلوع_الشمس_من_مغربها_وخروج_الدابة\nاتكلمنا المرة إللي فاتت عن يأجوج ومأجوج وخروجهم وشوفنا إزاي ربنا خلّص الأرض منهم وبعدها نزل عيسى عليه السلام والمؤمنون معاه من جبل الطور وهنا يبدأ حكم عيسى عليه السلام،\nورسول الله ﷺ قال :\n\"من أدرك منكم عيسى ابن مريم فليقرأه مني السلام\"\nيعني إللي يعيش لحد ما ينزل عيسى عليه السلام  يوصل له سلام رسول الله ﷺ،\nوسيحج عيسى عليه السلام و يعتمر بعد قتله للدجال واستقرار الأمور،\nقال رسول الله ﷺ:\n\"وَالَّذِي نَفْسِي بِيَدِهِ، لَيُهِلَّنَّ ابْنُ مَرْيَمَ بِفَجِّ الرَّوْحَاءِ ، حَاجًّا أَوْ مُعْتَمِرًا، أَوْ لَيَثْنِيَنَّهُمَا\"\nوالرّوْحَاء مكان بين المدينة ووادي الصفراء في طريق مكة.\nالفترة إللي فاتت من قبل حتى خروج الدجال كانت كلها قحط وابتلاءات، فبعد ما خلاص اتخلصوا من يأجوج ومأجوج هيبدأ حكم عيسى عليه السلام وتبدأ مهمته في تحكيم شريعة الإسلام؛ \nفيكسر الصليب ويقتل الخنزير ويضع الجزية، \nواتكلمنا عن الحاجات دي بالتفصيل المرة إللي فاتت،\nوهنا بقى ربنا هيأمر الأرض إنها تُخرج بركاتها،\nفتبدأ الأرض تُنبت بسرعة وبكثرة لدرجة إن لو حد رمى بذر على جبل الصفا، يعني أرض الجبل هتنبت وتطلع ثمار،\nوالثمار إللي هتطلع من الأرض بصفة عامة هتكون مختلفة عن أي مرة طلعت فيها قبل كده،\nالثمرة الواحدة حجمها هيبقى كبير جدا لدرجة إنها تكفي مجموعة من الناس،\nيعني مثلا شايفين الرّمان حجمه بيكون صغير إزاي والواحدة مبتكفيش فرد واحد،\nفي الوقت ده بقى الرمانة الواحدة هتكفي مجموعة أفراد،\nومش بس كده ده هيستظلوا بالقشرة الخارجية بتاعتها \nقال رسول الله ﷺ:\n\"ثم يقال للأرض: أنبتي ثمرتك، ورُدي بركتك، فيومئذ تأكل العصابة من الرمانة ويستظلون بقَحفِها\"\nوعنقود العنب الواحد يكفي مجموعة من الناس،\nعنقود العنب إللي ممكن الواحد يخلصوا في قاعدة ويبقى عايز غيره\nفتخيلوا حجم عنقود العنب هيبقى عامل إزاي\nومش بس كده ده الحيوانات نفسها هتسمن ويفيض لبنها وهينتهي الرعي؛ لأن مفيش حد محتاج للرعي أصلا،\nلأن الخير منتشر في الأرض كلها،\nوالغنمة الواحدة تكفي أربعين إنسان،\n\"واللّقحة من الغنم لتكفي الفخذ من الناس\"\nقال رسول الله ﷺ:\n\"وَاللَّهِ لَيَنْزِلَنَّ ابْنُ مَرْيَمَ حَكَمًا عَادِلًا ، فَلَيَكْسِرَنَّ الصَّلِيبَ ، وَلَيَقْتُلَنَّ الْخِنْزِيرَ ، وَلَيَضَعَنَّ الْجِزْيَةَ ، \nوَلَتُتْرَكَنَّ الْقِلَاصُ فَلَا يُسْعَى عَلَيْهَا ، وَلَتَذْهَبَنَّ الشَّحْنَاءُ وَالتَّبَاغُضُ وَالتَّحَاسُدُ ، وَلَيَدْعُوَنَّ إِلَى الْمَالِ فَلَا يَقْبَلُهُ أَحَدٌ \"\nوالقلاص معناها الإبل القوية،\nويفيض المال لدرجة إن الواحد ييجي يطلع صدقة ميلاقيش حد ياخدها من كثرة الخير إللي الناس فيه،\nودي علامة من العلامات الصغرى إللي حصلت في زمن عمر بن عبد العزيز وقلنا إنها هتحصل تاني في آخر الزمان وده وقتها،\nده غير الأمان إللي هينتشر بين الناس كلهم وكمان بين الحيوانات المفترسة وبين الناس،\nيعني الذئب هيرعى مع الغنم عادي كأنه كلبها إللي بيحرسها، والأسود تعيش وسط الناس،\nوالأطفال هيلعبوا مع الثعابين لدرجة إن الطفل يضع يده في فم الثعبان فلا يؤذيه؛ لأن ربنا هيكون نزع منها سمومها،\nقال رسول الله ﷺ:\n\"وَتَقَعُ الْأَمَنَةُ فِي الْأَرْضِ ،حَتَّى يَرْعَى الْأَسَدُ مَعَ الْإِبِلِ ، وَالنَّمِرُ مَعَ الْبَقَرِ ، وَالذِّئَابُ مَعَ الْغَنَمِ ، وَتَلْعَبُ الصِّبْيَانُ بِالْحَيَّاتِ لَا يَضُرُّ بَعْضُهُمْ بَعْضًا \"\nوربنا هينزع الكُره بين الناس ومش هيبقى فيه شحناء ولا بغضاء بينهم،\nومش هيبقى في الأرض غير عبادة الله ومش هيبقى في شرك وطبعا مش هيكون في حروب؛ لأن الحرب أو الجهاد كان عشان نشر الدين دلوقتي كل الناس مؤمنين ومفيش بينهم مشاكل فمفيش أي داعي للحرب،\nيعني تقدروا تقولوا إنها جنة مصغرة على الأرض في الوقت ده، بيعبر عنها رسول الله ﷺ ويقول:\n\"طُوبَى لِعَيْشٍ بَعْدَ الْمَسِيحِ \"\nيعني بالعامية كده يا بخت إللي هيعيش بعد حكم المسيح،\nوهيفضل الحال كده لحد ما عيسى عليه السلام يكمّل فترة حياته في الأرض أربعين سنة من بعد نزوله،\nيعني هو كان عاش قبل رفعه ثلاثة وثلاثين سنة ولما ينزل هيعيش كمان أربعين سنة،\nقال رسول الله ﷺ:\n\"فَيَقْتُلُ الدَّجَّالَ ثُمَّ يَمْكُثُ عِيسَى فِي الْأَرْضِ أَرْبَعِينَ سَنَةً\"\n☆هنا في سؤال :\nإيه موضوع إن عيسى يقعد في الأرض بعد نزوله سبع سنين وهو كان عمره ثلاثة وثلاثين قبل رفعه للسماء وبكده يكمل الأربعين سنة\nخلونا نشوف حديث رسول الله ﷺ، \nقال رسول الله ﷺ عن هلاك الدجال وإن عيسى هو إللي هيقتله:\n\" فَيَبْعَثُ اللهُ عِيسَى ابْنَ مَرْيَمَ كَأَنَّهُ عُرْوَةُ بْنُ مَسْعُودٍ ، فَيَطْلُبُهُ فَيُهْلِكُهُ، ثُمَّ يَلْبَثُ النَّاسُ《 بَعْدَهُ》 سِنِينَ سَبْعًا ، لَيْسَ بَيْنَ اثْنَيْنِ عَدَاوَةٌ\"\nشايفين كلمة بعده دي\n بعض العلماء قالوا إن المقصود بيها هو الدجال وإن عيسى عليه السلام هيعيش بعد هلاك الدجال مع الناس سبع سنين وخلاص يموت،\nلكن القول الصحيح إن كلمة 《بعده》 المقصود بها عيسى عليه السلام مش الدجال، يعني الناس هيعيشوا بعد موت عيسى عليه السلام سبع سنين مفيش أي عداوة بينهم،\nأو إنهم هيعيشوا في زمن عيسى نفسه سبع سنين مفيش بينهم أي شحناء أوبغضاء،\nأما عيسى عليه السلام فهيعيش أربعين سنة بعد الدجال لحديث رسول الله ﷺ:\n\" يَلْبَثُ أَرْبَعِينَ سَنَةً ، ثُمَّ يُتَوَفَّى ﷺ، وَيُصَلِّي عَلَيْهِ الْمُسْلِمُونَ\"\nفعيسى عليه السلام هيعيش في الأرض يحكم بشريعة الإسلام وتهلك كل المِلل والأديان الثانية لمدة أربعين سنة،\nوعيسى عليه السلام هو آخر الصحابة موتا\nعيسى عليه السلام قابل رسول الله ﷺ في الإسراء والمعراج وآمن به فهو صحابي، \nغير باقي الأنبياء إللي قابلهم رسول الله ﷺ؛ لأن عيسى عليه السلام رُفع حيا إلى السماء،\nوجاء في آخر الزمان وطبّق شريعة الإسلام،\nطبعا منزلة النبوة والرسالة أعظم من منزلة الصُّحبة، فإثبات الصحبة له لن يزيده رفعة ولا مكانة،\n لكن بنقولها كمعلومة بما إن عيسى عليه السلام توفرت فيه شروط صحبة رسول الله ﷺ،\nحتى إن بعض العلماء سأل بعض تلاميذه، مَن في الصحابة أفضل من أبي بكر الصديق، فمحدش عرف فقال لهم: عيسى عليه السلام \nبعد موت عيسى عليه السلام الناس هتقعد فترة من الزمن على نفس منهجه ومفيش بينهم أي مشاكل والفترة دي هي سبع سنين زي ما قلنا من شوية،\nبعد السبع سنين هيبدأ يحصل الضلال مرة تانية في الناس وتبدأ البدع في الظهور مرة تانية،\nوتتكرر نفس المأساة إللي حصلت بعد نوح عليه السلام وبعد هود وبعد صالح وبعد كل نبي،\nالناس يكونوا على الإيمان ومع الوقت الشيطان يُغويهم ويضلهم لحد ما يقعوا في الشرك مرة ثانية،\nويظهر الفساد من جديد، مع إنهم كانوا لسه شايفين آيات ومعجزات بعينهم وعيسى عليه السلام كان وسطهم، لكن البشر وضلالهم للأسف\nالمرة دي بقى الأحداث هتحصل بسرعة لأن نهاية الدنيا قربت،\nبعكس ما كان بيحصل أيام نوح والأنبياء من بعده كان في فترة زمنية لكن دلوقتي مفيش وقت فالأحداث والنزول للهاوية بيكون أسرع، ومع ذلك كله هيستمر وجود القِلة المؤمنة بين الناس\nمع زيادة الكفار في الأرض وانتشار الشرك وقلة المؤمنين، هتبدأ العلامات الكبرى إللي تقفل باب التوبة في الظهور\nوهي طلوع الشمس من مغربها وخروج الدابة،\nأي واحدة منهم تخرج الأول فالتانية تخرج وراءها على طول،\nيعني الشمس لو طلعت من المغرب الأول وراها على طول خروج الدابة،\nولو الدابة خرجت الأول وراها على طول طلوع الشمس من مغربها،\nقال رسول الله ﷺ:\n\" إن أول الآيات خروجاً: طلوع الشمس من مغربها، وخروج الدابة على الناس ضُحى، وأيهما ما كانت قبل صاحبتها، فالأخرى على إِثرها قريب\"\nودي العلامة الرابعة والخامسة من علامات الساعة الكبرى، \n◇العلامة الرابعة: طلوع الشمس من مغربها \nوالعلامة دي موجودة في الآية:\n\"هَلْ يَنْظُرُونَ إِلَّا أَنْ تَأْتِيَهُمُ الْمَلَائِكَةُ أو يَأْتِيَ رَبُّكَ أو يَأْتِيَ بَعْضُ آيات رَبِّكَ يَوْمَ يَأْتِي بَعْضُ آيات رَبِّكَ لَا يَنْفَعُ نَفْسًا إيمانها لَمْ تَكُنْ آَمَنَتْ مِنْ قَبْلُ أو كَسَبَتْ فِي إيمانها خَيْرًا قُلِ انْتَظِرُوا إِنَّا مُنْتَظِرُونَ\"\nومعنى الآية:\nهم الناس إللي مستمرين على ظلمهم وعنادهم دول مستنيين إيه عشان يؤمنوا؟!\nمستنيين يأتيهم مقدمات العذاب ومقدمات الآخرة عن طريق الملائكة إللي تيجي تقبض أرواحهم؟!\nما همّ لو وصلوا للمرحلة دي وهمّ على ظلمهم وعنادهم وكفرهم خلاص مش هينفعهم إيمانهم بعد كده ولا هينفعهم أي عمل صالح\nولّا مستنيين إن ربنا يأتي عشان يَفصِل ويقضي بين العباد ويُجازي المحسنين والمسيئين؟!\nوالمقصود في الآية بيوم يأتي بعض آيات ربك هو طلوع الشمس من مغربها،\n¤إيه بقى قصة طلوع الشمس من مغربها دي\nخلينا نعرف الإجابة من رسول الله ﷺ،\nفي يوم من الأيام لما الشمس غربت؛ رسول الله ﷺ كان واقف ومعاه أبو ذر، \nفسأله رسول الله ﷺ:\nانت عارف الشمس بتروح فين بعد ما بتغرب؟\nفقال أبو ذر رضي الله عنه: الله ورسوله أعلم!\nفقال رسول الله ﷺ:\nكل يوم الشمس بعد ما بتغرب بتروح تسجد تحت عرش الرحمن، وبعدين تستأذن في الخروج من جهة الشرق زي عادتها كل يوم؛ فيؤذن لها بالخروج من الشرق،\nلحد ما ييجي يوم وتستأذن في الخروج من الشرق فلا يُؤذن لها، ويقال لها :\nارجعي من حيت جئتِ، فتطلع من مغربها\nفالشمس بتسير في كل يوم وليلة، وهي مش ثابتة في السماء، دي بتتحرك وبتروح تسجد كمان وربنا قال: \n\"وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ \"\nطيب بتسجد إزاي، الله أعلم \nاحنا بنؤمن إنها بتسجد وإن كنا منعرفش طريقة السجود،\nزي بالضبط كده إيماننا بتسبيح الطيور والجمادات وكل شيء ولكن احنا لا نفقه تسبيحهم،\n\"وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ وَلَكِنْ لَا تَفْقَهُونَ تَسْبِيحَهُمْ  \"\nفبعد ما الشمس تطلع من مغربها كل الناس على الأرض هيشوفوها وساعتها كل البشر هيؤمنوا بالله ولكن لا ينفعهم إيمانهم خلاص، لا ينفع إسلام كافر، ولا ينفع توبة عاصي\nقال رسول الله ﷺ:\n\"لَا تَقُومُ السَّاعَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا ، فَإِذَا رَآهَا النَّاسُ آمَنَ مَنْ عَلَيْهَا ، فَذَاكَ حِينَ : \n\"لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ\"\nوقال:\n\" مَنْ تَابَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا ، تَابَ اللَّهُ عَلَيْهِ\"\n☆طيب ليه لا يُقبل توبة تائب ولا إسلام كافر\nلأن طلوع الشمس من مغربها آية عظيمة تنكشف عندها الحقائق، ويُؤمن الناس غصب عنهم، ويشوفوا من الأهوال إللي يخلي الكافر يضطر للدخول في الإسلام، ويضطر العاصي للتوبة،\nزي ما حصل مع فرعون كده، فاكرين\nفضل ظالم ومعاند بعد كل الآيات إللي شافها ولما خلاص كان بيغرق وعرف إن مفيش مفر قال :\nآمنت أنه لا إله إلا الذي آمنت به بنو إسرائيل،\nفهنا مينفعوش إيمانه لأنه انقطع عنه الإيمان بالغيب وبقى شايف قصاده الآيات إللي مفيش منها مفر ولا فيها أي تشكيك\nوحتى المؤمن لا ينفعه العمل صالح ولا يُقبَل منه لو مكنش بيعمله قبل طلوع الشمس،\nيعني لو واحد مؤمن ومكنش بيعمل أعمال صالحة كتير؛ لو طلعت الشمس من مغربها وراح مزود في أعماله الصالحة لن تنفعه أعماله الصالحة دي،\nتنفعه لو كان مواظب عليها من قبل طلوع الشمس من مغربها وهيفضل ياخد أجرها،\nقال رسول الله ﷺ:\n\" ولا تزال التوبة مقبولة حتى تطلع الشمس من المغرب، فإذا طلعت طُبع على كل قلبٍ بما فيه، وكُفِيَ الناس العمل\"\n☆طبعا ممكن حد يسأل ويقول طيب والناس إللي هتتولد بعد كده ذنبها إيه يتقفل عنها باب التوبة \n◇أولا:\n احنا منعرفش المدة إللي بين طلوع الشمس من مغربها وبين قيام الساعة أد إيه بالضبط، \nفي الحديث إن العلامات بتحصل وراء بعضها بسرعة جدا\nفممكن بعد طلوع الشمس من مغربها ميبقاش في وقت لمواليد جُدد وتحصل باقي العلامات في زمن قليل ممكن شهور وتنتهي الدنيا\n◇ثانيا: \nخلونا نفترض يعني إن في مواليد بعد طلوع الشمس من مغربها، ربنا العادل لن يظلم البشر مثقال ذرة،\nفلعل يكون لهم اختبار يوم القيامة زي أهل الفترة كده أو لهم  وضع خاص بهم،\nاحنا معندناش حاجة في الإسلام بتتكلم عن النقطة دي لأنها بصفة عامة مش هتفيدنا بشيء،\nوفي قول 《ضعيف》لبعض أهل العلم بيقول:\nإن غلق باب التوبة عند طلوع الشمس من مغربها خاص بأهل ذلك الزمان إللي شافوا الآية دي قصادهم، \nفلو تطاول الزمان بعد كده لحد ما نُسي خبر طلوع الشمس من مغربها أو كان يُخبر عنه آحاد من الناس: صحت التوبة والإسلام في ذلك الزمان،\nلكن زي ما قلت القول ده ضعيف؛ لأن كل الأحاديث بتدل على إن باب التوبة إذا أُغلق لا يفتح مرة ثانية أبدا\nالشاهد من الكلام إن ربنا لا يظلم مثقال ذرة، فلو جاء مواليد لا يستحقون العذاب لن يعذبهم الله \n☆عندنا سؤال كمان\n هي الشمس لما تطلع من المغرب هتطلع على كل أهل الأرض في وقت واحد، وهتفضل تطلع من المغرب للأبد\nمن المحتمل إن الناس هتشوف طلوع الشمس من مغربها على حسب توقيتهم وحسب مطلعهم زي ما كانوا متعودين طول عمرهم،\nومفيش مانع إنها هتطلع لكل أهل الأرض من المغرب ويشوفوها كلهم في نفس الوقت بقدرة الله، ويكون ده من جُملة الآيات ومن مظاهر اختلال نظام الكون كله\nأما طلوعها من المغرب فهيكون مرة واحدة فقط،\nوفي قول بيقول إنه طلوعها من المغرب هيكون لمدة ثلاثة أيام وبعدين ترجع تطلع مرة ثانية من المشرق.\n◇العلامة الخامسة وإللي هتيجي بعد طلوع الشمس من مغربها : خروج الدابة\nقال الله تعالى:\n\"وَإِذَا وَقَعَ الْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَابَّةً مِنَ الأرض تُكَلِّمُهُمْ أَنَّ النَّاسَ كَانُوا بِآياتنَا لَا يُوقِنُونَ\"\nومعنى إذا وقع القول عليهم: \nإذا وَجبت الحُجّة عليهم إذ أنهم لم يأمروا بالمعروف ولم ينهوا عن المنكر، \nوقيل إن المراد ما وُعدوا به من مشارطة قيام الساعة، يعني إذا حصل خروج الشمس من مغربها تطلع الدابة تكلم الناس،\nوالدابة دي هتخرج في وقت الضحى، \nقال رسول الله ﷺ:\n\" إن أول الآيات خروجاً: طلوع الشمس من مغربها، \n《وخروج الدابة على الناس ضُحى》، وأيهما ما كانت قبل صاحبتها، فالأخرى على إِثرها قريب\"\nوفي الغالب هيبقى خروجها في نفس اليوم إللي هتكون طلعت فيه الشمس من مغربها،\nيعني الشمس خلاص أشرقت من المغرب في يوم، وفي نفس اليوم لما ييجي وقت الضحى تخرج الدابة، \nوالحكمة في كده إن عند طلوع الشمس من المغرب يُغلق باب التوبة، فتخرج الدابة تُميّز المؤمن من الكافر تكميلاً للمقصود من إغلاق باب التوبة،\nوالدابة دي هتخرج من الأرض، يعني ملهاش أب أو أم، ربنا هيخرجها من الأرض زي ما أخرج ناقة صالح عليه السلام من الصخرة من غير أم ولا أب،\nبالنسبة لشكلها إيه أو صفتها إيه؛ فاحنا منعرفش\nمفيش حديث عن رسول الله ﷺ بيوضح إيه هي الدابة دي، إللي نعرفه عنها إنها حيوان يتكلم مع الناس،\nوالعلماء اجتهدوا بقى، في إللي قال إنها من فصيلة ناقة صالح، وفي إللي قال إنها ناقة صالح نفسها،\nوأقوال تانية إنها الثعبان إللي كان تحت الكعبة يحمي كنز الكعبة،\nوقيل إنها لمّا تخرج هيخرج معاها عصا موسى وخاتم سليمان، وجاء في وصفها أوصاف عجيبة، لكن كل ده ليس عليه أي دليل من أحاديث رسول الله ﷺ الصحيحة\nفلو وصل لكم أي وصف عن الدابة اعرفوا إن ده اجتهاد من العلماء لكن مفيش أي دليل زي ما قلنا على شكلها عامل إزاي،\nوطبعا مش هي الجسّاسة إللي كانت على الجزيرة مع الدجال إللي اتكلمنا عنها قبل كده،\nالدابة هتكلم الناس وتَسِمُهُم على خراطيمهم، قال رسول الله ﷺ:\n\"تخرج الدابَّة فتسِم الناس على خراطيمهم \"\nالخرطوم هو الأنف، والوَسْم معناه الكَىّ، والناس بيستعملوه عشان يميزوا الدواب، زي طبعة كده على الجلد\nفالمقصود هنا إن الدابة دي هتختم على أنوف الناس بختم،\nفيبقى المؤمن له سِمة والكافر له سِمَة مختلفة عنه،\n في روايات بتقول إنها هتطبع على المؤمن كلمة مؤمن وعلى الكافر كلمة كافر لكنها روايات ضعيفة،\nلكن الصحيح الثابت إنها هتختم الناس على أنوفهم،\nوالناس دي هتكثر ويعمروا في الأرض،\nوالواحد يروح يشتري البعير منهم، لما يسأل اشتراه منين يقول اشتريته من واحد من المُخطّمِين، فهيبقوا معروفين بين الناس،\nقال رسول الله ﷺ:\n\"ثم يَغْمُرُونَ فيكم ، حتى يشتري الرجل البعير ، فيقول : ممن اشتريته ؟ فيقول : اشتريته من أحد المخطَّمين\"\nيعني إللي مختوم على أنفه،\n☆آخر سؤال معانا النهاردة\n قلنا من شوية حديث رسول الله ﷺ إن أول الآيات ظهورا طلوع الشمس من مغربها والدابة،\n إزاي رسول الله ﷺ يقول كده وكان قبلهم الدجال ويأجوج ومأجوج ونزول عيسى عليه السلام \nشوفوا، \nالأَوّلية هنا أولية في الأشياء الغير مألوفة، يعني الدجال وعيسى عليه السلام ويأجوج ومأجوج مهما كانوا فهم بشر،\nأيوة في خوارق وفي معجزات من عيسي عليه السلام ، وخوارق من الدجال، وعجائب من يأجوج ومأجوج، \nلكن مش زي طلوع الشمس من مغربها وخروج حيوان من الأرض يكلم  الناس ويصفهم بالإيمان والكفر، فخروج الدابة أول الآيات الأرضية الغير معتادة،\nوطلوع الشمس من مغربها على غير عادتها المألوفة أول الآيات السماوية وهي أول الآيات المُؤذنة بتغير العالم العلوي وتنتهي الآيات السماوية بقيام الساعة\n♡ملحوظة مهمة:\nكل الكلام إللي بقوله لكم هو كلام مختصر، بجيب فيه الخلاصة عشان يبقى عندكم فكرة أساسية عن كل موضوع، وإلا ففي أحاديث وآيات وشروح كثيرة للعلماء، \nوكل مرة بحط في التعليقات المصادر عشان تقدروا تتوسعوا وتعرفوا معلومات أكثر\nإيه الأحداث إللي هتحصل بعد خروج الدابة وطلوع الشمس من مغربها، ده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 155, "l": "الجزء 129 | علامات الساعة الكبري الجزء العاشر | الدخان والخسوف الثلاثه", "u": "https://www.facebook.com/groups/710210019782034/permalink/827963901339978/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وتسعة_وعشرون\n#علامات_الساعة_الكبرى_الجزء_العاشر\n#الدخان_والخسوف_الثلاثة\nاتكلمنا المرة إللي فاتت عن طلوع الشمس من مغربها وخروج الدابة، \nهتيجي بعد كده العلامة السادسة من علامات الساعة الكبرى وهي الدخان، ربنا بيقول:\n\"فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ\"\nواحنا منعرفش الدخان هيخرج امتى بالضبط، لأن مفيش ترتيب واضح بين علامات الساعة الكبرى،\nيعني هل الدخان هيكون قبل الدجال، ولّا بعد طلوع الشمس من مغربها وخروج الدابة، الله أعلم\nإللي نعرفه إن الدخان من علامات الساعة الكبرى إللي هتحصل آخر الزمان وهيشهدها المؤمن والكافر، \nوهو ده القول الراجح، لأن في ثلاثة أقوال تانيين مش موضوعنا \nوالدخان بصفة عامة هو ما يُطلق على ما يتصاعد عند إيقاد الحطب، \nفهيظهر دخان عظيم جاي من السماء يملأ الأرض كلها بسبب ترك الحق، وكثرة المعاصي، سواء قبل الدجال أو بعده،\nفيخاف الناس من الدخان ويصيبهم الهلع والجزع ويفكروه عذاب أليم،\nفالأرض هتكون عاملة زي بيت مليان دخان،\nعارفين لما حاجة تشيط على البوتاجاز أو تتحرق مثلا وتطلع دخان ويملأ البيت والدخان يخلي الواحد يكح؟\nأهه هيبقى الوضع شبيه بكده لكن أشد بكتير وخصوصا إن مفيش مكان تاني الواحد ممكن يروح فيه عشان يقدر يتنفس هواء نقي،\nيعني احنا ممكن نفتح شبابيك البيت أو حتى نخرج برة البيت عشان ناخد نفسنا، لكن الدخان بقى هيكون مالي الأرض كلها، عارفين زي إيه\nزي الضباب أو الشّبُّورة إللي بتكون موجودة الصبح في أيام الشتاء كده، بتكون مالية الدنيا زي الدخان،\nوالدخان لن ينجو منه أحد ولا يفر منه مخلوق، يُعذِّب به الكفار أشد العذاب، أما المؤمن فلا يصيبه منه إلا كما تُصيب الزكمةُ الإنسان، يعني كأن عنده زكام، برد يعني\nقال رسول الله ﷺ:\n\"إن ربكم أنذركم ثلاثاً وذكر منها :الدخان، يأخذ المؤمن كالزَّكمة ويأخذ الكافر فينتفخ حتى يخرج من كل مَسْمعٍ منه\"\nالمؤمنين هيكونوا قليلين جدا في الزمن ده بالنسبة للكفار وهتكون أعمالهم مختلطة، يعني حسنات وسيئات، ومع انتشار العصيان والكفر في الأرض، هتُهدم الكعبة على يد ذو السُّوَيْقَتيْن وهيُرفع القرآن وتخرب المدينة وهيرجع الناس تاني لعبادة الأصنام، قال رسول الله ﷺ:\n\"لا يذهب الليل والنهار حتى تُعبد اللّات والعُزّى\"\nفالسيدة عائشة قالت لرسول الله ﷺ :\n\"إن كنت لأظن حين أنزل الله: هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَلَوْ كَرِهَ الْمُشْرِكُونَ\" أن ذلك تاماً \"\nيعني هي فكرت إن لما ربنا أنزل الآية دي خلاص مش هيحصل عبادة أصنام مرة ثانية،\nفقال لها رسول الله ﷺ:\n \"إنه سيكون من ذلك ما شاء الله ثم يبعث الله ريحا طيبة فيُتوفى كل مَن في قلبه مثقال حبة خردل من إيمان، فيبقى مَن لا خير فيه فيرجعون إلى دين آبائهم\"\nيعني فعلا هيكون التوحيد موجود لفترة معينة لحد ما تأتي ريح تقبض أرواح مَن كان في قلبه مثقال حبة من خردل من إيمان.\n◇والكلام ياخدنا لعلامة تانية من علامات الساعة الصغرى المتداخلة في الكبرى وهي الريح الطيبة إللي تقبض أرواح المؤمنين.\nبعد خروج الدابة وختمها للناس وانتهاء الأعمال هتيجي ريح باردة طيبة ليّنة من الشام تقبض أرواح المؤمنين،\nإللي هيكونوا اتوجهوا أصلا للشام قبل خروج نار من قعر عدن تسوق الناس لأرض المحشر في الشام، وهنعرف تفاصيل النار دي لما نتكلم عنها،\nفالريح دي مش هتسيب إنسان في قلبه مثقال ذرة من خير أو إيمان إلا قبضته، لدرجة إن لو إنسان دخل في عمق الجبل الريح دي هتدخل وراه وتقبض روحه،\nقال رسول الله ﷺ:\n\"يرسل الله ريحاً باردة من قِبَل الشام، فلا يبقى على وجه الأرض أحداً في قلبه مثقال ذرة من خير أو إيمان إلا قبضته، حتى لو أن أحدكم دخل في كبد جبل لدخلت عليه حتى تقبضه\"\nويتبقى شرار الخلق، يعني أسوأ ناس على وجه الأرض هيكونوا في سرعتهم للشرور وقضاء الشهوات والفساد زي طيران الطائر في سرعته،\nوهيكونوا في العدوان وظلم بعضهم بعض زي السّباع المعتدية،\nقال رسول الله ﷺ:\n\"فَيَبْقَى شِرَارُ النَّاسِ، فِي خِفَّةِ الطَّيْرِ وَأَحْلَامِ السِّبَاعِ، لَا يَعْرِفُونَ مَعْرُوفًا وَلَا يُنْكِرُونَ مُنْكَرًا\"\n☆طيب وحديث رسول الله ﷺ:\n\"لا تزال طائفة من أمتي ظاهرين على الحق إلى يوم القيامة\"\nمش كده هيبقى في تعارض، يعني فين بقى الطائفة إللي على الحق وكده مبقاش غير شرار الخلق\nمفيش تعارض لأن المعنى المقصود إنهم هيفضلوا على الحق  لحد ما تيجي الريح اللينة وتقبضهم جميعا في وقت قريب جدا من يوم القيامة، وطبعا الأحداث الأخيرة دي هتحصل بسرعة جدا.\n☆إيه بقى قصة هدم الكعبة ورفع القرآن ؟\nفي آخر الزمان هيُرفع القرآن وتُهدم الكعبة وتَخْرّب المدينة ويهجرها الناس ولا يسكنها إلا السباع،\nعن عبد الله بن مسعود رضي الله عنه قال:\n\" لَيُسْرَيَنَّ عَلَى الْقُرْآنِ ذَاتَ لَيْلَةٍ فَلا يُتْرَكُ آيَةٌ فِي مُصْحَفٍ وَلا فِي قَلْبِ أَحَدٍ إِلا رُفِعَتْ \"\nيعني هييجي يوم تُرفع فيه كل آيات القرآن من المصاحف ومن قلب أي واحد عارف ولو آية واحدة من القرآن،\nوعادي جدا إن يكون في مسلمين حافظين بعض آيات القرآن ومش بيصلوا ولا بيعملوا أعمال صالحة، زي في عصرنا دلوقتي، فدول هيترفع القرآن من قلوبهم،\nوكمان عادي يكون في كفار حافظين بعض آيات القرآن في في آخر الزمان ويترفع من صدورهم هم كمان،\nفي عصرنا دلوقتي بنشوف نصارى بيحفظوا القرآن كله بغرض الطعن فيه أو لأي غرض تاني فمش حاجة غريبة لو لقينا في آخر الزمان كفار حافظين بعض الآيات وترفع من قلوبهم،\n☆طيب ليه يُرفع القرآن\nطب وهو السبب أصلا في نزول القرآن كان إيه؟\n مش لهداية الناس على مر الزمان من بعثة رسول الله ﷺ لحد النهاية، \nطيب دلوقتي خلاص مبقاش موجود غير الكفار إللي لن يؤمنوا وهم شرار الخلق، حتى المؤمنين قلة وخلاص باب الإيمان والتوبة والاستزادة من الأعمال الصالحة اتقفلت ومبقاش في صلاة ولا صيام ولا حج وبعد وقت بسيط جدا لن يُذكر في الأرض 《الله الله》\nفإيه الفايدة من وجود القرآن دلوقتي \nوكمان ربنا يَغار إن كتابه يبقى في الأرض بلا فائدة ولا يُعمل به، فيرفعه سبحانه ولا يبقى منه كلمة ولا حتى حرف\nأما هدم الكعبة،\n فهييجي واحد اسمه ذو السُّوَيْقَتَين من الحبشة إللي هي أثيوبيا في زماننا دلوقتي عشان يهدمها،\nفهيخربها وياخد الكنز المدفون فيها ويجرد الكعبة من كسوتها ويهدمها حجر حجر،\nواسمه ذو السُّوَيْقَتَين لأن رجله ضعيفة وقصيرة فيها تباعد، مقوّسة يعني وهو أسود وأصلع،\nومحدش يعرف إيه هو كنز الكعبة المدفون ده، في كنز في الكعبة لكن إيه هو بالضبط؟ مفيش تفصيل عنه، إللي نعرفه إن إللي هيستخرج الكنز ده هو هادم الكعبة ذو السويقتين،\nقال رسول الله ﷺ:\n1-\"يُخَرِّبُ ‏ ‏الْكَعْبَةَ ‏ ‏ذُو السُّوَيْقَتَيْنِ\"\n2-\"كَأَنِّي أَنْظُرُ إِلَيْهِ أَسْوَدَ أَفْحَجَ يَنْقُضُهَا حَجَرًا حَجَرًا\"\n3-\"يُخَرِّبُ ‏الْكَعْبَةَ ‏‏ذُوالسُّوَيْقَتَيْنِ ‏ ‏مِنْ ‏‏الْحَبَشَةِ،‏‏ \nوَيَسْلُبُهَا حِلْيَتَهَا وَيُجَرِّدُهَا مِنْ كِسْوَتِهَا، وَلَكَأَنِّي أَنْظُرُ إِلَيْهِ ‏أُصَيْلِعَ ، ‏أُفَيْدِعَ ‏‏يَضْرِبُ عَلَيْهَا ‏بِمِسْحَاتِهِ ‏‏وَمِعْوَلِهِ\"\nوطبعا ده لا يتعارض مع قول ربنا في القرآن:\n\"أَوَلَمْ يَرَوْا أَنَّا جَعَلْنَا حَرَمًا آمِنًا\" \nلأن ساعتها مش هيكون في مؤمنين وشريعة الحج مش هتبقى موجودة زي دلوقتي مثلا، المؤمنين هيكون أعدادهم قليلة،\nوكمان الآية مفيهاش أي دلالة على استمرار الأمن للنهاية\n☆وهنا في سؤال بمناسبة الآية إللي قلناها،\nاحنا اتكلمنا قبل كده في جزء تاريخ الكعبة على مر الزمن إن الكعبة اتهدمت أكثر من مرة وحصل فيها قتل الحَجَيج وسُرِق الحجر الأسود على أيدي القرامطة، فين الأمان بقى\nكنت قلت لكم قبل كده إن السنة هي الجزء الثاني من الوحي، يعني عشان نفهم القرآن محتاجين أحاديث رسول الله ﷺ،\nرسول الله ﷺ قال إن محدش هيقدر يستبيح بيت الله الحرام إلا المسلمين أنفسهم،\nيعني الحرم موجود آمن بنص القرآن، لكن كلام رسول الله ﷺ بيوضح لنا إن الأمن ده مقيد بشرط، وهو إن إللي هينتهك الأمن ده هم المسلمون ومش حد غيرهم،\nقال رسول الله ﷺ:\n\"وَلَنْ يَسْتَحِلّ هَذَا الْبَيْت إِلَّا أَهْله\"\nولو رجعنا لتاريخ الكعبة هنلاقي إن كل إللي تعدى عليها هم المسلمون، شوفنا الحجاج لما ضرب الكعبة بالمنجنيق، وشوفنا القرامطة وإللي عملوه وهم أصلهم من المسلمين،\nلكن مفيش حد من غير المسلمين استباح الكعبة إطلاقا من زمن رسول الله ﷺ لحد زماننا دلوقتي،\nوده من الدلائل على صدق نبوة رسول الله ﷺ، لأن مين هيعرف الغيب إن محدش غير المسلمين هيستبيح البيت غير عالم الغيب والشهادة وهو إللي أخبر رسوله ﷺ بكده\nهيعيش الناس في الفترة دي بعد موت المؤمنين يعني، أسوأ فترات الدنيا، حتى يُقال إن فترتهم أسوأ من فترة الجاهلية الأولى،\nيقول رسول الله ﷺ:\n\"وَيَبْقَى شِرَارُ النَّاسِ يَتَهَارَجُونَ فِيهَا تَهَارُجَ الْحُمُرِ\"\nيعني يُجَامع الرجال النساء بِحَضْرَةِ النَّاس كَمَا يفعل الْحَمِير،\nوده إللي اتكلمنا عنه قبل كده لو تفتكروا ،وقلنا إن هييجي يوم الرجل هيزني بالمرأة في الشارع كده علنًا عادي ومحدش هيكلمه،\nوهيكون أحسن واحد ساعتها هو إللي هيقول له :\nلو إنك تزني بيها وراء الجدار أحسن!\nويتمثل لهم الشيطان ويقول لهم :\nألا تستجيبون؟! يعني تسمعوا كلامي\nفيسألوه: فما تأمرنا، يعني عايزنا نسمع كلامك في إيه\nفيأمرهم بعبادة الأصنام ويعبدوها فعلا، ودي عودة عبادة اللات والعزى إللي قلناها من شوية في حديث رسول الله ﷺ، \nقال رسول الله ﷺ:\n\"فَيَتَمَثَّلُ لَهُمْ الشَّيْطَانُ فَيَقُولُ أَلَا تَسْتَجِيبُونَ ؟ فَيَقُولُونَ : فَمَا تَأْمُرُنَا ؟ فَيَأْمُرُهُمْ بِعِبَادَةِ الْأَوْثَانِ\"\nوبالنسبة لخراب المدينة، فالناس هيهجروها ومش هيبقى فيها حد غير السباع والطيور، والناس مش هتهجر المدينة بسبب قلة الثمار مثلا وإن المدينة بقت فقيرة؛ لأ ده هيتركوها رغبة عنها وهي أحسن ما تكون والثمار إللي فيها هتكون غذاء للسباع والطيور،\nقال رسول الله ﷺ:\n\" لَيَتْرُكَنَّهَا أَهْلُهَا عَلَى خَيْرِ مَا كَانَتْ مُذَلَّلَةً لِلْعَوَافِي\" والعوافي يعني السباع والطيور،\nوبعد كده تحصل العلامات السابعة والثامنة والتاسعة من علامات الساعة الكبرى وهي:\nخسف بالمشرق وخسف بالمغرب، وخسف بجزيرة العرب،\n☆وبرده احنا منعرفش بالتحديد العلامة دي قبل الدخان ولّا قبل حتى خروج الدجال، \nلأن مفيش حديث فيه ترتيب واضح لعلامات الساعة الكبرى، غير في الدجال ونزول عيسى وبعده يأجوج ومأجوج، غير كده مفيش حديث عن رسول الله ﷺ يقطع بترتيب علامات الساعة الكبرى،\nوالعلامات دي بتحصل وراء بعض بسرعة جدا زي ما قلنا قبل كده\nوالخسف معناه نزول شيء ما على الأرض إلى باطن الأرض\n يعني الأرض تتشق وتبلعه، \nوحصل بعض الخسوفات في أماكن متفرقة و في أزمان متباعدة وده كان من علامات الساعة الصغرى،\nأما الخسوفات الثلاثة دي هتكون عظيمة وعامة لأماكن كثيرة من الأرض في مشارقها ومغاربها وفي جزيرة العرب محصلتش قبل كده هتُدمِّر مناطق واسعة من الأرض وتُخرِّب ما عليها وتتغير أحوال الناس وتضطرب معايشهم،\nقال رسول الله ﷺ:\n\"لا تقوم الساعة حتى تروا عشر آيات: فذكر منها ثلاثة خسوف: خسف بالمشرق، وخسف بالمغرب، وخسف بجزيرة العرب\"\nوبكده يبقى مش باقي لنا غير آخر علامة من علامات الساعة الكبرى، هنتكلم عنها الجزء الجاي إن شاء الله،\nوالجزء الجاي هيكون الجزء الأخير من سلسلة علامات الساعة"}, {"n": 156, "l": "الجزء 130 | علامات الساعة الكبري الجزء 11 والاخير | نار تسوق الناس الي محشرهم", "u": "https://www.facebook.com/groups/710210019782034/permalink/828980494571652/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثلاثون\n#علامات_الساعة_الكبرى_الجزء_الحادي_عشر_والأخير\n#نار_تسوق_الناس_إلى_محشرهم\nوقفنا المرة إللي فاتت عند آخر علامة من علامات الساعة الكبرى وهي:\n ◇خروج نار من قَعْر عدن في اليمن تقود الناس إلى محشرهم،\nقال رسول الله ﷺ لما كان بيذكر علامات الساعة الكبرى:\n\" وَآخِرُ ذَلِكَ نَارٌ تَخْرُجُ مِنَ الْيَمَنِ ، تَطْرُدُ النَّاسَ إِلَى مَحْشَرِهِمْ\"\nوهي على ظاهر الحديث نار مش حمم بركانية زي ما كان في بعض الناس بتقول\nو الأصل في ألفاظ الكتاب والسنة إنها تُحمَل على ظاهرها وعلى حقيقتها\nالمهم، \nقبل ما النار تظهر، المؤمنين وهم خيار الناس في الزمن ده هيكونوا هاجروا للشام طواعية،\n قال رسول الله ﷺ:\n\"إِنَّهَا سَتَكُونُ هِجْرَةٌ بَعْدَ هِجْرَةٍ لَخِيَارِ النَّاسِ إِلَى مُهَاجَرِ إِبْرَاهِيمَ\" \nوالشام هي المكان إللي هاجر إيه إبراهيم عليه السلام لما ترك قومه وخرج هو وزوجته سارة وابن أخيه لوط، واتكلمنا عنهم بالتفصيل في قصص الأنبياء لو تفتكروا\nفالمؤمنون لما يوصلوا للشام الريح الطيبة هتقبض أرواحهم زي ما قلنا المرة إللي فاتت ويتبقى شرار الخلق وتحصل الأمور إللي اتكلمنا عليها المرة إللي فاتت وبعدين تخرج بقى النار الحاشرة،\nوالنار دي أول الآيات التي لا شيء بعدها من أمور الدنيا، \nيعني مش زي باقي الآيات إللي فاتت كان بيبقى بعدها أشياء من أمور الدنيا،\nلأ، الآية دي هي أول علامة لبداية الآخرة لأن بعدها كل حاجة في الدنيا هتنتهي فلما تنتهي النار هيحصل النفخ في الصور وتبدأ أحداث الآخرة، \nلما سأل عبد الله بن سلام اليهودي رسول الله ﷺ ما هي أول أشراط الساعة قال له رسول الله ﷺ:\n\"أما أول أشراط الساعة: فنار تحشرهم من المشرق إلى المغرب\"\nوالنار دي غير النار إللي خرجت من أرض الحجاز إللي أضاءت لها أعناق الإبل ببصرى في الشام واتكلمنا عنها في علامات الساعة الصغرى \nالنار الحاشرة دي هتخرج من قعر عدن في اليمن، يعني دي بدايتها، وبعد كده تنتشر في كل الأرض، تذهب إلى المشرق فتحشر أهل المشرق إلى الشام، \nوبعدين تذهب إلى المغرب، فتحشر أهل المغرب إلى الشام، فهي تعم الأرض وتأتى بكل الناس في الأرض إلى الشام غصب عنهم،\nوالنار هتاخدهم لأرض الشام بالذات لأنها المكان إللي ستقوم فيه الساعة ويموت فيه آخر جيل من البشرية، \nوالناس في الحشر ده على ثلاث طرائق:\n¤الأول:\nراغبين راهبين راكبون طاعمون يعني من نفسهم كده توجهوا للشام وكلهم هيكونوا راكبين على دواب ومعاهم كل زاد الرحلة،\nعارفين زي ما الواحد بيسافر سفر درجة أولى كده وبيبقى مرتاح وعنده كل الخدمات\n¤الثاني:\nهيتجه الناس للشام اثْنَانِ عَلَى بَعِيرٍ، وَثَلاَثَةٌ عَلَى بَعِيرٍ، وَأَرْبَعَةٌ عَلَى بَعِيرٍ، وَعَشَرَةٌ عَلَى بَعِيرٍ،\nيعني ناس هتتوجه للشام يمشوا شوية ويركبوا شوية، ومن قلة المركوبات من الدواب، كل اتنين هيبدّلوا على بعير،\n وكل ثلاثة هيبدلوا على بعير لحد ما يوصلوا إن كل عشرة يبدلوا على بعير، يعني واحد يركب والتاني يمشي شوية،\nوالراكب ينزل يمشي والماشي يركب، ويفضلوا على الحال ده لحد ما يوصلوا\n¤القسم الثالث:\nوَيَحْشُرُ بَقِيَّتَهُمُ النَّارُ، تَقِيلُ مَعَهُمْ حَيْثُ قَالُوا، وَتَبِيتُ مَعَهُمْ حَيْثُ بَاتُوا، وَتُصْبِحُ مَعَهُمْ حَيْثُ أَصْبَحُوا، وَتُمْسِي مَعَهُمْ حَيْثُ أَمْسَوْا\"\nيعني الباقين تحشرهم النار غصبا، تفضل وراهم وتدفعهم لأرض المحشر وإللي يتخلف وميرضاش يتحرك النار تأكله ويحترق بالنار الحاشرة،\nوالناس طبعا ماشيين مسافات طويلة فأكيد هيتعبوا فلما يتعبوا ويقعدوا يريحوا النار هتقف ومش هتتقدم لحد ما يريحوا وبعدين تبدأ تتحرك معاهم مرة تانية وهكذا لحد ما يوصلوا للشام،\nوفي الوقت ده هيكون في قِلة في الدواب إللي الناس هيركبوها بسبب إن حصل مرض أهلك معظم الدواب،  والواحد ممكن يبيع بستان كبير في مقابل دابة يركبها ومحدش يرضى يشتريه منه،\nيعني كأن مثلا واحد يدفع مليون جنيه في مقابل حمار أو جمل يركبه، ومع ذلك ميلاقيش، \nقال رسول الله ﷺ:\n\" يُلقِي الله الآفة على الظهر فلا يبقى ظهر، حتى أن الرجل ليكون له الحديقة المُعْجبة فيعطيها بالشارف ذات القَتَب فلا يقدر عليها\"\nوبكده يجتمع الناس كلهم في مكان واحد في الشام في بيت المقدس إللي هتقوم فيه الساعة فهي أرض المحشر والمنشر،\nوهيتبقى رجلين راعيان للغنم من قبيلة مُزَيْنة هما آخر من يُحشر، \nوهم معديين على المدينة ومعاهم الغنم بتاعهم هيلاقوها فاضية مفيهاش غير السّباع والطيور وأول ما يوصلوا ثَنْية الوداع مكان قريب من المدينة هيقعوا على وجوههما ميتين،\nقال رسول الله ﷺ:\n\" وآخِرُ مَنْ يُحشَرُ راعِيانِ من مُزيْنةَ يُريدانِ المدينةَ ، يَنْعِقَانِ بغنمِهما ، فيَجِدانِها وُحوشًا ، حتى إذا بلَغا ثَنِيَّةَ الوداعِ ، خَرَّا على وُجوهِهِما\"\n☆طيب إزاي بقى هتقوم الساعة\nفي يوم جمعة بعد ما الناس تُحشر؛ صاحب القرن هينفخ في القرن نفخة عظيمة فالناس هيسمعوها ويتفزعوا ويُصعقوا ويموتوا كلهم في نفس الوقت،\nقال رسول الله ﷺ:\n\"إن من أفضل أيامكم يوم الجمعة، فيه خُلق آدم وفيه قُبض، وفي النفخة وفيه الصعقة\"\nالقَرن معناه حاجة زي البُوق إللي بيطلّع صوت، واسمه قرن لأنه بيشبه قرن الثور،\nصاحب القرن هو مَلك من الملائكة اسمه إسرافيل على الراجح من أقوال العلماء، وهي دي مهمته إللي ربنا خلقه لها، ماسك القرن وينظر إلى العرش مستني الأمر بالنفخ في الصور، \nقال رسول الله ﷺ:\n\"كَيْفَ أَنْعَمُ وَصَاحِبُ الْقَرْنِ قَدِ الْتَقَمَ الْقَرْنَ، وَاسْتَمَعَ الإِذْنَ حَتَّى يُؤْمَرَ بِالنَّفْخِ فَيَنْفُخ\"\nفأول ما ربنا يأمره بالنفخ هينفخ في البوق نفخة عظيمة جدا أول واحد هيسمعها رجل يَلوط حوض إبله،\nيعني إيه؟\nالإبل لما تيجي تشرب بيعملوا لها حوض من طوب ويغطوه من برة بالأسمنت بحيث إنه ميسربش مية،\nففي واحد هيكون بيطين الحوض ويصلحه من برة عشان يضع في الحوض مية ويسقي الإبل، هو ده أول واحد هيسمع صوت الصُّور أو القرن فيُصعق يموت يعني،\nويسمعه باقي الأحياء في السماوات والأرض فيُصعقون كلهم إلا مَن شاء الله، يعني في فئة لن تُصعق، \nفي رواية بتقول إنهم الملائكة أو بعض كبار الملائكة، ورواية تانية بتقول إنهم أهل الجنة من الحور العين والولدان المخلدون، والله أعلم مين إللي مش هيصعق بعد النفخة دي،\nقال تعالى:\n\"وَنُفِخَ فِي الصُّورِ فَصَعِقَ مَنْ فِي السَّمَوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ\"\nوالصوت إللي هيخرج ده هيبقى عبارة عن صيْحة عظيمة جدا تملأ الدنيا، وأول ما تبدأ الصيحة هتبدأ ضعيفة مش هيسمعها غير الرجل إللي قلنا عليه من شوية يلوط حوضه فيُصعق،\n وبعدين تبقى أقوى ومحدش يسمعها إلا أصغى إليها، \nزي كده لما نسمع صوت غريب ونبدأ نسكت عشان نسمع كويس، أهه ده بالضبط هيكون الحال،\nوالناس هيكونوا بيمارسوا حياتهم عادي وقت ما يُصعقوا، يعني واحد هيكون حلب الناقة بتاعته وواخد اللبن ورايح يشربه فيسمع الصيحة فيُصعق،\nوواحد تاني هيكون بياكل فييجي يرفع اللقمة لفمه فميلحقش يضعها في فمه فيسمع الصيحة فيُصعق،\nورجلين نشرا ثوب بينهما واحد بيعرضه للبيع على التاني فيسمعوا الصيحة فيصعقان، فلا يلحقوا يشتروه ولا يلحقوا يطبقوه،\nقال رسول الله ﷺ:\n\"ولَتَقُومَنَّ الساعةُ وقد نشر الرجلانِ ثوبَهما بينَهما ، فلا يَتَبايَعَانِهِ ولا يَطْوِيانِهِ ، ولَتَقُومَنَّ الساعةُ وقد انصرف الرجلُ بلَبَنِ لِقْحَتِه فلا يَطْعَمُه ، \nولَتَقُومَنَّ الساعةُ وهو يَلِيطُ حَوْضَه فلا يَسْقِي فيه ، ولَتَقُومَنَّ الساعةُ وقد رفع أُكْلَتَه إلى فِيهِ فلا يَطْعَمُ\"\nفالساعة هتأتي بغتة، والناس دول هم شرار الخلق وآخر جيل موجود في الدنيا، وبكده يموت كل البشر إللي كانوا على الأرض بعد ما يسمعوا النفخة الأولى في الصور،\nوفي نفخة تانية هتحصل وهيسمعها كل البشر في القبور ويقوموا من قبورهم للحساب،\nوبين النفخة الأولى والثانية 《أربعين》 أربعين يوم ولّا أربعين شهر ولّا أربعين سنة، الله أعلم \nهي جاءت في الحديث أربعين فقط، قال رسول الله ﷺ :\n\" ما بين النفختين أربعون\"\nوبكده يبقى احنا خلصنا علامات الساعة\nكلمة أخيرة:\nطبعا احنا شوفنا في الواقع إن في علامات كتير من علامات الساعة الصغرى اتحققت وبتتحقق، وده يزود الإيمان في قلوبنا ونزداد يقين بالآخرة،\nوكل ما كان عندنا يقين بالآخرة وإننا هييجي يوم ونقف قصاد ربنا ونتحاسب على كل شيء كل ما هنقلل من الذنوب ونتمسك بالأعمال الصالحة أكثر؛ لسببين مهمين:\n◇أولا: \nلأن دي وصية رسول الله ﷺ لما قال:\n\"إنَّهُ مَن يعِشْ منْكم بعدي فسيَرى اختِلافًا كثيرًا فعليكُم بسنَّتي وسنَّةِ الخلفاءِ الرَّاشدينَ المَهديِّينَ من بعدي تمسَّكوا بِها وعضُّوا عليها بالنَّواجذِ،\n وإيَّاكم ومُحدَثاتِ الأمورِ فإنَّ كلَّ بدعةٍ ضلالةٌ\"\nيعني رسول الله ﷺ بيقول لنا هتشوفوا اختلاف كتير وهتشوفوا الفتن والمُغريات حولكم كتير وأهل الحق هيكونوا قليلين، \nوهيبقى في بدع، فالحل مش إنكم تتبعوا الرُّخص وتمشوا وراء الناس بحجة إن ده زمن فتن واحنا مش قادرين نعمل حاجة ونعمل زي ما الناس بتعمل وخلاص،\nلأ، الحل في التمسك بسنة رسول الله ﷺ،\nبيقول لنا عضوا عليها بالنواجذ،\nعارفين يعني إيه، يعني تمسكوا بسنتي بكل قوتكم، مش تسيبوا السنة عشان هي سنة، إللي يسيب سنة رسول الله ﷺ هيقع في يوم من الأيام وهيضل وده أمر واقع وفي أمثلة كتير جدا على كده \n◇السبب الثاني هو إن العبادة في الهَرج، يعني في زمن الفتن وكثرة القتل أجرها وثوابها زي ثواب الهجرة إلى رسول الله ﷺ،\nقال رسول الله ﷺ:\n\" العبادة في الهرج كهجرة إليّ\"\nوالعبادة معناها كل ما يحبه الله ويرضاه من الأفعال الظاهرة والباطنة، سواء كانت فرض أو سنة، والسبب في الأجر العظيم ده إن الناس في زمن الفتن بيكونوا في غفلة وبينشغلوا بالفتن، فتنة الأفلام والأغاني والتصوير وسهولة الوصول للحرام وغيرها وغيرها من الفتن،\nفلما يكون في واحد يسيب الفتن دي كلها ويعبد ربنا ويتمسك بمنهج رسول الله ﷺ والصحابة فده معناه إن الإنسان ده قلبه معمور بمحبة الله ومنشغل بذكره وعبادته سبحانه\n☆علامات الساعة بتعلمنا :\n◇البعد عن الفتن مهما كنا مفكرين إيماننا قوي، زي الدجال كده، مَن سَمع به فليبتعد عنه، أيوة احنا في الغالب مش هنحضر الدجال لكن الفتن كتيرة جدا حوالينا لازم نبعد عنها.\n◇بتعلمنا ناخد بالنا ولا نأكل إلا الحلال ونبعد عن الربا.\n◇بتعلمنا الحرص على العلم الشرعي الصحيح والحذر من \nأدعياء العلم إللي بيفتوا الناس وبيضلوهم سواء بقصد أو بدون قصد.\n◇وبتعلمنا صلة الرحم، وحُسن الجوار، وإفشاء السلام بين كل الناس وبتعلمنا التمسك الأمانة.\n◇وبتعلمنا عدم التفاخر بالدنيا، سواء بيوت أو أموال أو مراكز علمية أو غيرها.\nكل واحد يقدر يشوف هو اتعلم إيه من علامات الساعة ويطبقه في حياته حتى لو كان لوحده في الطريق إلى الله،\nفالإسلام بدأ غريبا وعاد غريب \nالقيامة مش بس إللي هتحصل في آخر الزمان، ولكن من مات فقد قامت قيامته، يعني هيشوف إللي له من خير وإللي عليه من شر،\nفالقيامة وإن كانت بعيدة فالموت أقرب للإنسان من شِراك نعله، واحنا شوفنا إن من علامات الساعة كثرة موت الفجأة، فهل احنا مستعدين للقيامة للصغرى مع إنها أقرب؟\nأسأل الله العظيم رب العرش الكريم أن يرزقنا وإياكم حسن الخاتمة ويثبت قلوبنا على الإيمان حتى نلقاه\n☆ملحوظة حديث :\n《 إذا مات أحدكم فقد قامت قيامته》\nحديث موضوع لا يصح عن رسول الله ﷺ، لكن المعنى صحيح، فأنا قلته ككلام مش كحديث\nإن شاء الله من المرة الجاية هنرجع للأحداث الخارجية للدولة الإسلامية في عهد رسول الله ﷺ  وهنشوف رسائل رسول الله ﷺ للملوك لدعوتهم للإسلام"}]);
